CASOS PRÁCTICOS DESARROLLADOS
manda ante el juez competente, solicitando que Juan pague Sos arrendamientos pendien
tes más una indemnización, y de no ser así, que Je entregue el inmueble arrendado. ¿Ante
qué tipo de acumulación estamos?
Si Pedro interpone demanda ante el Juez competente, solicitando que Juan pague los arren
damientos pendientes más una indemnización, y de no ser así, que le entregue el inmueble
arrendado, estaríamos ante un caso de Acumulación Objetiva Originarla Autónoma. La mis
ma que si bien no está regulada expresamente, es posible solicitarla debido a que el artículo
87o del CPC, tiene un sistema númems apertus en relación a las formas de acumulación obje
tiva, en tanto se cumple con la misma vía procedimental, competenciay exista conexidad. La
acumulación autónoma implica que el juez analizará los elementos de cada pretensión de
manera independiente, y en la sentencia debe resolverse motivando por separado.
19. Llega en casación un proceso judicial en el que se cuestiona la interpretación de la ins
tancia anterior sobre cuál es el efecto del emplazamiento válido con la demanda. En tal
sentido, se debe tener en cuenta que el emplazamiento con la demanda:
El emplazamiento válido con la demanda produce los siguientes efectos:
1. La competencia inicial no podrá ser modificada, aunque posteriormente varíen las cir
cunstancias que la determinaron.
2. El petitorio no podrá ser modificado fuera de los casos permitidos en este Código.
3. No es jurídicamente posible iniciar otro proceso con el mismo petitorio.
4. Interrumpe la prescripción extintiva.
20. María es Juez y además alumna de una maestría de derecho procesal, de igual forma,
losé es abogado y también es alumno de la misma maestría de derecho procesal. Indepen
dientemente de esa situación, losé es actualmente abogado y asesora a una de las partes
en un proceso que viene siendo conocido por M aría como Juez.
Conforme los hechos expuestos en el caso no generan causales de impedimento2 ni de recu
sación3.
2 Art. 305 C.RC. El juez se encuentra impedido de dirigir un proceso cuando: 1. Ha sido parte anteriormente en
éste; 2. Él o su cónyuge o concubino, tiene parentesco dentro del cuarto grado de consanguinidad, segundo
de afinidad o de adopción con alguna de las partes o con su representante o apoderado o con un abogado
que interviene en el proceso; 3. Él o su cónyuge o concubino, tiene el cargo de tutor o curador de cualquiera
de las partes; 4. Ha recibido él o su cónyuge o concubino, beneficios, dádivas de alguna de las partes, antes
o después de empezado el proceso, aunque ellos sean de escaso valor; 5. Ha conocido el proceso en otra
instancia, salvo que haya realizado únicamente actos procesales de mero trámite; o
El impedimento previsto en la segunda causal sólo se verifica cuando el abogado ya estaba ejerciendo el
patrocinio de la causa. Está prohibido al abogado asumir una defensa que provoque el impedimento del juez.
3 Art. 307 C.RC. Las partes pueden solicitar que el juez se aparte del proceso cuando: 1. Es amigo íntim o o
enemigo manifiesto de cualquiera de las partes, demostrado por hechos inequívocos; 2. Él o su cónyuge o
concubino o su pariente en la línea directa o en la línea colateral hasta el segundo grado, primero de afinidad
o adoptado, tienen relaciones de crédito con alguna de las partes; salvo que se trate de persona de derecho
o de servicio público; 3. Él o su cónyuge o concubino, son donatarios, empleadores o presuntos herederos de
alguna de las partes; 4. Haya intervenido en el proceso como apoderado, miembro del Ministerio Público,
perito, testigo o defensor; 5. Tiene interés directo o indirecto en el resultado del proceso; y, 6. Exista proceso
vigente entre él o su cónyuge o concubino con cualquiera de las partes, siempre que no sea promovido con
posterioridad al inicio del proceso.
