21. Carlos y Candelaria, quienes domicilian en Hwaraz» celebran un contrato de compraven
ta respecto a un vehículo. Víctor» quien domicilia en Lima» se entera de este acto jurídico y
decide demandar su nulidad ante el Juez del Juzgado Especializado Civil de Lima. Es co
rrecto afirmar que:
El juez de Lima puede declarar improcedente la demanda, pero por falta de legitimidad para
obrar, pues en el caso no se da información respecto de la condición de Víctor. Distinto hubiera
sido si por lo menos se decía que Víctor era un tercero con legítimo interés, es decir, alguien a
quien el acto materia de nulidad le significaría un perjuicio económico o moral. Si fuera este el
caso, es decir, que Víctores un tercero con legítimo interés, el juez de Lima no podría declarar
improcedente, a pesar de que territorialm ente es incompetente, pues este presupuesto proce
sal admite la prórroga,y en todo caso estaría sujeto a que las partes formulen o no la excepción
de incompetencia territorial, ya que, de no ser así, y, por el contrario, los demandados se aper
sonan y contestan la demanda, estaríamos ante un caso de prórroga tácita. Las notificaciones
se realizarían por exhorto al juzgado de igual clase en Huaraz.
22. Un Juez ha emitido una sentencia declarando fundada una demanda de nulidad de
acto jurídico. El demandado apela la sentencia solicitando: (i) que la sentencia sea revoca
da por haberse incurrido en un error de apreciación en los hechos que configuran la causal
de nulidad invocada; (ii) que la sentencia sea revocada por incurriren un error de interpre
tación de la norma de derecho material aplicada al caso. Cuando la Sala Civil de la Corte
Superior analiza el caso, advierte que la sentencia de primera instancia no ha sido debida
mente motivada. Es correcto afirmar:
La Sala puede declarar la nulidad de la sentencia por indebida motivación, a pesar de que ésta
no fue alegada por el demandado.
2 3 . Francisco interpone una demanda para que se declare la resolución de un contrato de
arrendamiento por falta de pago, así como para que le paguen la renta adeudada y se orde
ne la devolución del bien arrendado. La sentencia de primera instancia declarada fundada
la demanda y ordena la resolución del contrato y el pago de la renta adeudada, pero omite
pronunciarse respecto a la pretensión de devolución del bien. Es correcto afirmar:
La sentencia es nula al tener un vicio de incongruencia objetiva (infra petita o citra petita). La
incongruencia infra petita llamada también incongruencia citra petita se da cuando el juez en
su decisión final no emitió pronunciamiento sobre alguna de las pretensiones propuestas por
las partes o sobre un punto controvertido. Esta omisión pone en evidencia la falta de iden
tidad entre lo resuelto y lo pedido por las partes. Por ejemplo, si la demanda contiene una
acumulación objetiva, originariay accesoria de pretensiones, digamos como pretensión prin
cipal la resolución contractual y como pretensión accesorio la de indemnización por daños y
perjuicios, sin embargo, el juez solo resuelve la primera obviando la segunda, en tal caso la
incongruencia objetiva será citra petita. En este tipo de incongruencia se manifiesta como una
omisión de pronunciamiento, esta omisión quiebra la identidad entre lo pedido y lo resuelto
(si fueran pretensiones) o la falta de correlación entre los puntos controvertidos fijados y los
resueltos en la decisión (pues, se deben resolver todos, sin excepción). La incongruencia citra
petita es en realidad un supuesto de incongruencia omisiva en la que el juez guarda silencio de
las pretensionesy alegaciones postuladas por las partes4.
4 STC Exp. N °1333'' 2002-AA/TC.
