24o María tuvo un hijo con Felipe, que se ilama Héctor y tiene 08 años. Felipe no le da ali
mentos a Héctor. María en nombre de Héctor interpone una demanda solicitando que Feli
pe le otorgue una pensión de alimentos para Héctor. Es correcto afirmar que.
Solo el menor Héctor y Felipe tienen legitimidad para obrar en ese proceso. María actúa en
representación de Héctor porsersu madre de éstey por ser menorde edad (Art. 45 C.C.).
25. Isabel tiene interés en presentar una demanda de desalojo en defensa de un inmueble
de propiedad de su menor hijo Alvaro:
En este caso la legitimidad para obrar activa le corresponde al menor Alvaro, y si bien su mamá
podría interponer la demanda de desalojo, lo cierto es que la mencionada madre sólo tendría
la condición de representante (Art. 45-A C.C).
26. Josefina tiene 16 años y está casada con Martín. Josefina demanda a Carlos el pago de
una indemnización porque éste la atropelló con su auto. Usted es juez y está analizando la
validez de la relación procesal. Es correcto afirmar que:
Josefina no tiene capacidad procesal para demandar por una Indemnización. La incapacidad
cesa a partir del nacimiento del hijo únicamente para realizar algunos actos relacionados con
el menor. (Art. 46C.C)
27. Al calificar una demanda acumulada de resolución de contrato de compra venta, de
volución de bien e indemnización por daños y perjuicios, se advierte que en la cláusula
décima segunda del contrato materia de resolución, las partes han acordado: “Todas las
desavenencias que deriven del presente contrato o que guarden relación con este serán
resueltas definitivamente de acuerdo con el Reglamento de Arbitraje de la Cámara de Co
mercio Lima por uno o más árbitros nombrados conforme a este Reglamento, a cuya deci
sión se someten las partes en forma incondicional”; ante esta situación:
El juez deberá adm itir a trám ite la demanda, pues corresponderá al demandado deducir la
excepción de convenio arbitral dentro del plazo respectivo, caso contrario, se entenderá re
nunciado el derecho a invocarla.
28. Julio Andrade le debe S/. 2,000.00 a Juan Pérez; de otro lado, María Sarmiento le debe
S/. 1,000.00 a julio Andrade desde hace varios años. Juan Pérez interpone demanda contra
María Sarmiento a fin de que esta cumpla con pagar a julio Andrade los S/. 1,000.00 que le
debe. La demandada María Sarmiento deduce la excepción de Representación defectuo
sa o insuficiente del demandante, señalando que Julio Andrade no le ha otorgado poder
alguno a Juan Pérez. Usted, considerando que el artículo 1219o, inciso 4) del Código Civil
autoriza al acreedor a ejercer los derechos de su deudor, sea en vía de acción o para asumir
su defensa, cómo resolvería esta excepción:
La excepción es Infundada, porque Juan Pérez no actúa en representación de Julio Andrade;
sino, que se subroga en su lugar, conforme a la acotada norma legal.
29. Jorge celebra un contrato con Miguel mediante el cual Jorge le prestó a Miguel la can
tidad de S¡. zo o 000,00. Sin embargo, llegada la fecha en que Miguel debía devolver el di
nero prestado, no lo hace, razón por la cual Jorge decide demandar el pago de la suma de
dinero adeudada. Luego de declarado saneado el proceso, Jorge fallece dejando como su
único heredero a su hijo Saúl de 19 años. Saúl se apersona al proceso solicitando su incor
poración al mismo, anexando la respectiva sucesión intestada. Señale la opción correcta.
