Se debe adm itirsu incorporación al proceso porque se ha presentado un supuesto de sucesión
procesal. (Art. 108 inciso 1 C.PC.) El artículo 108 del Código Procesal Civil (...), “señala que por la
sucesión procesal un sujeto ocupa el lugar de otro en un proceso, al reemplazarlo como titular
activo o pasivo del derecho discutido, precisando en el inciso 1 que se presenta la sucesión
