partes perdió la titularidad del derecho discutido. Sin embargo, si transcurridos treinta días no
comparece el sucesor al proceso, éste proseguirá con un curador procesal, nombrado a pedido
de parte”. Exp. N.0 ooni-20i2-PA/TC-Lima. Fj.3.
30. La Ley N° 30007 reconoce derechos sucesorios entre un varón y una mujer libres de im
pedimento matrimonial que conforman una unión de hecho. Para efectos de la presente
ley es requisito que:
La Ley N° 30007 establece que la unión de hecho o concubinato deberá reunir los requisitos del
artículo 326 del Código Civil, es decir, que sea voluntaria, realizada por un varón y una mujer, libres
de impedimento matrimonial, que hay durado por lo menos 02 años continuos, para alcanzar fi
nalidades y cumplir deberes semejantes a los del matrimonio. El concubinato debe estar vigente
al momento del fallecimiento de cualquiera de sus miembros, es decir, la ley sólo establece efectos
sucesorios para las uniones de hecho perfectas. Con esta Ley se reconocen derechos sucesorios a los
miembros de las uniones de hecho inscritas en el Registro Personal, de conformidad con el artículo
49 de la Ley N° 26662, o las reconocidas por la vía judicial, ya que el conviviente puede solicitar el
reconocimiento judicial de la unión de hecho si antes del fallecimiento del causante o conviviente,
no se hubiera realizado la inscripción registral.
31. Pedro demanda a Luis sobre obligación de dar suma de dinero, por la suma de cien mil
nuevos soles sin embargo luego de haberse fijado los puntos controvertidos Luís cancela
el monto de diez mil nuevos soles firmando un documento privado a Pedro, sin embargo,
a ese tiempo ya había transcurrido la etapa de ofrecimiento de medios de prueba por lo
que quiere incorporarlo al proceso marque la afirmación correcta sobre el ofrecimiento de
medios probatorios extemporáneos:
Se admite el medio probatorio extemporáneo pues la ley establece para el ofrecimiento de
medios de prueba extemporáneos cuando se refieren a hechos nuevos y cuando los hechos
son mencionados por la demandada al contestar la demanda o reconvenir.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1401 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
1. Juan desea matar a su esposa y decide hacerlo, pero tratando en todo momento de que
su conducta quede impune. De esta manera, decide iniciar una pelea con su esposa y pro
vocarla de tal manera que ella trate de golpearlo con un bate de béisbol y así atacarla si
mulando una defensa propia. Los hechos se dan como lo planeadoy]uan mata a su esposa.
Respecto a la conducta de Juan, es correcto indicar:
Estamos ante un supuesto de actio libera5, toda vez in causa que se montó un escenario perti
nente para pretender una causa de justificación indebida.
2. Manuel de quince años de edad, mientras caminaba por la calle observó a una adoles
cente que caminaba por la acera mientras conversaba por teléfono celular. Manuel, que
siempre anheló tener un teléfono celular, se fue aproximando lentamente hacia la adoles
cente y, en forma rauda, le arrebató su teléfono celularyse dio a la fuga. Sin embargo, en la
esquina siguiente fue detenido por personal de Serenazgo de la localidad.
En este caso concurre una causal de inim putabilidad prevista en el artículo 20.2 del Código Pe
nal, por lo que tenemos que aun cuando se advierte que la conducta de Manuel podría infrin
gir la legalidad, no se le puede atribuir culpabilidad, en tanto tiene la calidad de inimputable,
y en consecuencia excluido de sancionesy por el contrario sometido a medidas de protección
que deberán velar por su corrección.
Manuel por su edad es considerado un infractor penal, ello conforme a lo dispuesto por el
artículo l.i del Código de Responsabilidad Penal de Adolescentes que dispone: "El adolescente
entre catorce (14) y menos de dieciocho (18) años de edad, es sujeto de derechos y obligaciones, responde
por la comisión de una infracción en virtud de una responsabilidad penal especial, considerándose para
ello su edad y características personales”.
3. Rosario estaba en casa junto a su menor hija Clara, que dormía en su cama. Rosario pren
dió fuego al colchón, con el peligro no solo para la vida de esta sino también para el resto
de los ocupantes del inmueble. Cuando llegó la policía desalojó la vivienda y preguntó a
Rosario si quedaba alguien más dentro, a lo que contestó tranquila que quedaba su hija,
pero sin decir el lugar. Rosario se limitó a contemplar con tranquilidad cómo los bombe
ros extinguían el incendio. Clara fue encontrada muerta por los bomberos. Rosario actuó
con sus facultades intelectivas y volitivas levemente disminuidas debido a un trastorno de
personalidad histriónico agravado por la depresión leve que le aquejaba en la fecha de los
hechos.
En el caso de que Rosario haya actuado con dolo directo:
No exige la presencia de un conocimiento seguro. El dolo directo se refiere a la intención de
causar un resultado específico, y en este caso, Rosario parece haber actuado con tranquilidad
y sin mostrar preocupación por la seguridad de su hija ni de los demás ocupantes del inmue
ble. Esto sugiere que Rosario tenía la intención de causar el incendio y, por lo tanto, puede ser
5 Se trata de un hecho realizado por el agente en estado de Inimputabilidad, pero que dicho estado fue busca
do libremente por él, existiendo relación de causalidad entre el acto libre y el hecho típico realizado en estado
de inconsciencia.
