Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1402 of 1506 --

UBILEX
considerado como dolo directo, sin necesidad de que haya tenido un conocimiento seguro de
las consecuencias específicas del incendio.
4. Pedro saluda efusivamente a un amigo con varías palmadas en la espalda que le provo
can un atoramiento salival que a su vez le obstruye la tráquea hasta producirle la muerte
por asfixia.
Pedro no es responsable penalmente de la muerte de su amigo porque su conducta no califica
como una que genera el riesgo jurídico penalmente desaprobado del tipo penal de homicidio.
La muerte fue un resultado inesperadoy no directamente relacionado con la conducta de Pe-
dro, que simplemente saludó a su amigo con palmadas en la espalda. No se puede considerar
que Pedro haya causado la muerte intencionalmente, y su acción no se ajusta a los elementos
del delito de homicidio, que requiere una conducta que genere un riesgo jurídico penalmente
desaprobado.
5. Marco, salvavidas, observa a un bañista en situación de peligro. Debido a la bravura del
mar decide no intentar rescatarlo porque era muy probable que él también se ahogara.
El bañista muere ahogado. En tal sentido, desde el punto de vista del Derecho Penal, es
correcto afirmar que:
Marco ha cometido un hecho típicoy antijurídico, pero no culpable, pues no le es exigible una
acción tan peligrosa para su vida. Su decisión de no intentar rescatar al bañista debido a la
probabilidad de ahogarse él mismo es razonable y no puede ser considerada como una acción
que genere un riesgo jurídico penalmente desaprobado.
6. Esteban, ginecólogo con gran experiencia profesional y líder en su rubro, decidió practi
car a una paciente una ligadura de trompas durante un parto. La decisión la tomó sin contar
con el consentimiento de la mujer. Al respecto, cabe precisar que no era una intervención
necesaria técnicamente ni mucho menos urgente, puesto que su vida no corría peligro. Tan
solo era una intervención quirúrgica aconsejable desde el punto de vista médico, para evi
tar futuros embarazos que en el caso de la intervenida se presentaban de riesgo, además
que provenía de un hogar de escasos recursos económicos lo que significaba un potencial
sufrimiento para futuros hijos.
En el presente caso se llega a determinar que Esteban actuó erróneamente creyendo que
actuaba amparado en una causa de justificación, situación que de ser cierta se resolvería:
Como un error de prohibición indirecto (El error puede recaer sobre una causa de justificación
que la Ley no reconoce).
Aunque consideramos que la intervención era aconsejable médicamente para evitar futuros
embarazos de riesgo, dada la situación económica de la paciente, este procedimiento no era
técnicamente necesario ni urgente parasalvarsuvida. El errorde prohibición indirecto se con
figura cuando el agente cree erróneamente que su conducta está justificada por una causa
que la ley no reconoce como tal. En este caso, Esteban creyó que su intervención estaba jus
tificada por razones médicas y sociales, pero la ley no contempla estas circunstancias como
causas de justificación para realizar un procedimiento quirúrgico sin el consentimiento del
paciente.
7. Kike y Ari obstaculizaban el pase para los peatones en una calle por la que pasó ]on (a
quien Kike le tenía enemistad por un problema pasado), que tuvo que esquivarlos. Al re
tornar y verlos en el mismo lugar, ]on empujó a Kike, para luego este golpearle en la cara.
2 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1403 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
Luego, Ion acudió a un íbat donde ie dijeron que llevaba una gota de sangre en la cara, por
lo que decidió regresar a enfrentar a ICike. Ambos comenzaron una pelea, Kike le dio a Ion
un puñetazo en el ©f© izquierdo, quedándole como secuela la pérdida casi total de Sa fun
dón visual de dicho ojo en el que anteriormente se le había practicado un trasplante de
córnea a consecuencia del cual sufría una reducción de dicha función de un 30 % .
En referencia a la imputación objetiva en el caso expuesto:
Destaca en los delitos de resultado.
La conducta de KikeyAri de obstaculizare! pase para los peatones no es directamente relaciona
da con el resultado de la pérdida de visión de Jon. Sin embargo, la pelea que comenzó después
de que jon regresó y empujó a Kike puede ser considerada como el factor causal determinante
del resultado. La relación de causalidad entre la pelea y el resultado de la pérdida de visión es
objetiva,ya que la pelea fue el momento en que se produjo el daño a jon. Además, la relación de
riesgo entre la conducta de KikeyAri y el resultado de la pérdida de visión es objetivaba que su
conducta creó un riesgo de que jon se enfrentara a Kike y se produjera una pelea.
8. Diego conoció a Laura, ambos mayores de edad. Como Laura era fácilmente manipula-
ble, Diego le hizo creer que eran novios, y le propuso mantener relaciones sexuales, a lo
que Laura accedió llegándose a consumar el acto al menos en dos ocasiones. Como la ma
dre de Laura observó que un día su hija vomitaba le preguntó qué le ocurría, a lo que esta
contestó que quizás estuviera embarazada. La madre continuó preguntándole y esta le
confesó lo ocurrido con Diego. Laura presentaba un retraso mental moderado y no tenía
morfológicamente los signos claros del Síndrome de Down. Tenía un conocimiento básico
de la sexualidad, lo que impidió a Diego conocer la posible patología que sufría.
De tratarse de un error de tipo, ¿qué característica debe observarse?
El error de tipo no solo puede recaer sobre elementos normativos del tipo penal. La caracte
rística que debe observarse es que el error de tipo puede recaer sobre elementos que no son
normativos del tipo penal, como la condición de Laura de tener un retraso mental moderado
y no tener signos claros del Síndrome de Down. Este error de tipo es vencible, ya que Diego
podría haberse dado cuenta de la condición de Laura si hubiera investigado adecuadamente
antes de mantener relaciones sexuales con ella.
9. Diego Miranda es una persona sumamente olvidadiza. Diego salió de viaje y olvidó una
letra de cambio endosada al acreedor que iba a cubrir una deuda que se había comprome
tido a pagar al día siguiente. Al salir al aeropuerto, Diego puso en aviso a todos sus vecinos
que se iba de viaje y que, por favor, permanezcan atentos a su casa por temas de seguridad.
En ese contexto, Diego recordó la letra de cambio y optó por llamar a Luis, su vecino, para
que se acerque a su casa y suba por el techo, ingrese a su domicilio y se lleve el título valor
y le haga el favor de pagar la deuda pendiente. Luis hace lo que le pide Diego, cuando de
pronto, es observado por los vecinos, quienes confunden la situación y llaman a la policía.
Los agentes llegan al lugar de forma rápida, tanto que, al salir Luis, ellos estaban esperán
dolo en la puerta. De inmediato fue detenido y llevado a la comisaría.
Respecto a la conducta de Luis, es correcto afirm ar que:
Es atípica por falta de elemento subjetivo. Luis fue requerido por Diego para que subiera a la
casa y pagara la deuda pendiente. Aunque Luis no tenía conocimiento directo de la letra de
cambio ni de la deuda, su acción se ajusta a los elementos del delito de robo, ya que se trató
de la toma de un título valor sin el consentimiento del dueño. La falta de conocimiento de Luis
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1404 of 1506 --

UBILEX
sobre la letra de cambio no lo exime de responsabilidad penal,ya que su acción se ajusta a los
elementos del tipo penal.
Respecto a la conducta de los vecinos» se puede decir que:
Actúan bajo un error de tipo. Los vecinos confundieron la situación y llamaron a la policía
creyendo que algo inusual estaba sucediendo. Sin embargo, su acción no se ajusta a los ele
mentos del delito de denuncia falsa, ya que su error fue motivado por la confusión y no por
una intención dolosa. En este caso, se considera un error de tipo, ya que los vecinos no tenían
conocimiento de la situación real y actuaron bajo una creencia errónea.
10. Gloria se hallaba en trámites para obtener la separación de su esposo, Ignacio. No obs
tante, permanecían ambos en la vivienda conyugal. Gloria era objeto de continuos mal
tratos por parte de su esposo. Ante el temor de que tales episodios se repitieran y apro
vechando de que su esposo se hallaba en un cuarto situado en la azotea de la casa, cerró
con llave la puerta de comunicación de esta con la vivienda, dejando a Ignacio allí recluido,
bajo vigilancia estrecha de Gloria, que, apostada ante la reja, le amenazaba con echarle
aceite hirviendo si se acercaba. Ignacio, permaneció en dicha situación hasta el momento
que algunas personas de la vecindad alertaron a la Policía Nacional del Perú.
Respecto a la ubicación sistemática del miedo insuperable:
Para la doctrina mayoritaria es una causal de no exigibilidad de una conducta. Esto se basa en
que el miedo insuperable es un estado psicológico que puede llevar a la persona a actuar de
manera que no sea motivada por la norma, lo que Impide que se le Impute la responsabilidad
penal.
Respecto al concepto de miedo insuperable:
A diferencia del estado de necesidad justificante aquí el miedo es el fundamento de la excep
ción. El miedo insuperable se configura cuando la persona está dominada por un tem or serio
y no puede dirigir libremente su voluntad. En este sentido, el miedo es el móvil que determina
la acción, y no la necesidad de proteger un bien jurídico como en el caso del estado de nece
sidad.
11. Carlos hacía guardia en un polvorín, circunstancia por la que el comandante Benito le
entregó las llaves correspondientes a un taller. Aprovechando esto, Carlos extrajo un ba
lón de gasolina para reavivar el fuego de la estufa colocada en su dormitorio. Carlos dejó
al balón a un metro de una de las camas y a unos tres metros de la estufa, llenó su tapón
con gasolina,y dejando un reguero se dirigió hasta la estufa encendida contra la que lanzó
la gasolina que llevaba en el tapón, la cual prendió siguiendo el reguero hasta el mismo
balón que explotó dispersando el combustible inflamado. El lugar se prendió en llamas
donde estaba durmiendo el soldado de reemplazo Arturo, quien falleció.
Respecto a la responsabilidad penal de Benito:
No le es imputado el resultado porque el principio de confianza se manifiesta como un riesgo
permitido. Benito entregó las llaves del taller a Carlos, quien tenía la confianza de que no se
utilizarían para causar daño. El riesgo permitido se configura cuando se permite que los de
más actúen de manera que no sea lesiva, siempre y cuando no haya elementos que indiquen
que el tercero no cumplirá con su deber de no causar daño.
BALOTAR 10 DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1405 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
¿Eli qué casos no procede el principio de confianza?
Cuando el tercero no tiene capacidad para ser responsable. El principio de confianza se basa
en la idea de que los demás actuarán de manera responsable)/ no causarán daño. Si el tercero
no tiene capacidad para ser responsable, como en el caso de una persona con discapacidad o
una niña, no se puede confiar en que actuarán de manera responsable)/ el principio de con
fianza no procede.
12. Constantino, además de su profesión de gasfiter©, alquilaba un bar con otro socio, Ser
gio. Este le pedía que semanalmente le entregara unos S/ 200.00 a lo que aquel accedió
en al menos dos ocasiones ante el temor que le infundía y por el miedo a que espantara a
los clientes. Una tarde, cuando Constantino se encontraba en el parque con su amigo Car
los, apareció en aquel lugar Sergio. En un momento dado surgió una situación de conflicto
entre ellos, que provocó que Constantino se dirigiera a su vehículo y sacara una escopeta
de caza, propiedad de su padre, con la que, influenciado por el miedo que le tenía, llegó a
disparar al menos un cartucho contra Sergio, hiriéndole.
Siendo que Constantino creyó que Sergio se le acercaba con un arma blanca con ánimo de
matarlo:
Constantino actúa en legítima defensa putativa. La creencia de Constantino de que Sergio se
le acercaba con un arma blanca con ánimo de matarlo es una creencia subjetiva que, aunque
errónea, puede ser considerada como una legítima defensa putativa si se demuestra que fue
una creencia razonable)/fundada en las circunstancias del caso.
13. Leopoldo y Enrique irrumpieron en horas de la madrugada en la vivienda que habita
ban Emilio y Carlota, quienes se encontraban durmiendo. Ya dentro en la habitación de
la pareja golpearon a la mujer a partir de lo cual Emilio se abalanzó y empezó a golpear a
Leopoldo, no obstante, fue repelido por los asaltantes. Al temer por su vida y la de su com
pañera, dada la confusión del momento debido a la oscuridad del lugar y la desesperación
por protegerse de los sujetos que habían ingresado a su hogar, Emilio agarró un cuchillo de
cocina que encontró en la habitación y asestó a Leopoldo cinco cuchilladas que le produje
ron lesiones graves, mientras este y Enrique trataban de repeler el ataque.
Respecto a la legítima defensa, es correcto afirmar que:
Leopoldo y Enrique no pueden alegar legítima defensa bajo la premisa de que ellos nunca
usaron un cuchillo para su ataque.
¿Qué se requiere para que se configure miedo insuperable en Emilio?
Se requiere que el miedo sea causado por estímulos externos no patológicos, insuperable y
que el mal sea igual o mayor.
14. Arturo es contador de profesión y administrador de banca y finanzas. Ha tenido una
larga trayectoria pasando por diversos bancos prestigiosos. El 2013 decidió tomar una
oportunidad laboral para formar parte de la Superintendencia de Banca, Seguros - SBS.
El siguiente año se comprometió con Sara una abogada especializada en el sector labo
ral. Posteriormente conoce a su cuñado Jaider José, quien había regresado de los Estados
Unidos, quien le expuso que tiene algunos planes para ganar dinero. Jaider le refiere que
tiene cierta habilidad para descubrir los puntos débiles informáticos del sistema de datos
financieros, y que estos conocimientos pueden aprovecharse para afectar a los bancos en
Perú. Pedro no estaba interesado en ello, menos en perder su trabajo e incurrir en un de-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1406 of 1506 --

UBILEX
lito; no obstante, el mismo año se dio la llegada d-a su primer hijo, que, lamentablemente,
presentó una enfermedad de tratamiento costosísimo. Ante esta situación Pedro acepta la
propuesta de su cuñado y altera la base de datos del sistema de la S iS para cambiar el es
tado crediticio de Jaider, para que en su cuenta figure que cuenta con un saldo de sesenta
y cinco mil dólares.
Sobre la actuación de Arturo como agente activo del delito:
Comete un hecho agravado por su condición de agente con acceso privilegiado.
Arturo, como contadory administrador de bancay finanzas, tiene acceso privilegiado a la base
de datos de la Superintendencia de Banca, Seguros-SBS. Al alterar la base de datos para cam
biar el estado crediticio de Jaider, Arturo comete un delito agravado ya que se aprovecha de la
confianzay la autoridad que se le otorga por su profesión y posición.
En cuanto a la autoría y participación delictiva del presente caso:
Jaider actúa en calidad de instigador. Arturo, como agente con acceso privilegiado, realizó la
acción delictiva bajo la influencia de Jaider. Esto se considera Instigación, ya que Jaider no ac
tuó directamente, pero su ¡nfluenciay persuasión llevaron a Arturo a cometer el delito.
15. Teresa se dirigió al lugar donde residía su exesposo, Alberto. Allí lo abordó súbitamente
con un cuchillo de 11 cm de hoja, con el que le asestó varias puñaladas en la cara, el antebra
zo izquierdo y el pecho, tras enterarse que él había iniciado una nueva relación amorosa.
Alberto, como consecuencia del ataque, cayó al suelo donde Teresa prosiguió asestándole
cuchilladas y patadas por el cuerpo, loque provocó a Alberto la muerte. Cabe precisar que
Teresa es una paciente medicada. Al momento del hecho ya se encontraba clínicamente
como bipolar. En el momento de los hechos actuó con dicho mal.
Si se identificara que el actuar homicida de Teresa se vio influenciado por la emoción vio
lenta:
De acuerdo con la doctrina mayoritaria nacional Teresa es imputable. Si se identificara que
el actuar homicida de Teresa se vio influenciado por la emoción violenta, se consideraría que
actuó bajo el imperio de una emoción violenta que las circunstancias hicieron excusable. En
este caso, la emoción violenta se debe a la descubierta de la infidel idad de Alberto y la reacción
súbita de Teresa, que actuó bajo un estado de alteración mental causado por su condición de
paciente medicada y su trastorno bipolar.
En el caso de que haya intervenido una tercera persona en la muerte de Alberto a manos
de Teresa:
La participación en el delito de homicidio por emoción violenta ha sido reconocida por la ju
risprudencia nacional.
16. Jorge trabajaba como empleado en un restaurante en el que sus dueños se dedicaban a
falsificar tarjetas de crédito. Jorge copiaba las tarjetas auténticas que le daban los clientes
para pagar porque los dueños le habían obligado a hacerlo bajo amenazas de despedirlo y
hacer daño a su familia, exhibiéndole incluso fotografías de sus parientes que se hallaban
en su país de origen. A pesar de tener que realizar lo solicitado ante tales temores, Jorge
denunció inmediatamente los hechos a la policía.
¿Jorge respondería por el delito de falsificación?
No, porque el hecho realizado por Jorge es inexigible por estado de necesidad exculpante. El
estado de necesidad exculpante se refiere a la situación en que una persona se ve obligada a
6 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1407 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
cometer un delito debido a una circunstancia que la obliga a elegir entre dos males, y en este
caso, la alternativa es más grave que el delito cometido. En este sentido, si jorge actuó bajo
amenazas de despediday daño a su familia, su acción no puede considerarse como delictiva,
ya que se encuentra justificada por el estado de necesidad.
En caso de que Jorge haya actuado en estado de necesidad justificante:
El sujeto debe actuar conociendo que actúa justificadamente. El estado de necesidad ju sti
ficante se refiere a la situación en que una persona actúa para evitar un mal mayor. En este
sentido, si jorge actuó conociendo que su acción era justificada para evitar el daño a su familia,
entonces su responsabilidad penal sería menor, ya que se encuentra justificada por el estado
de necesidad.
17. Isidro se dirigió a una sucursal bancaria. Una vez allí encañonó con una pistola automá
tica al empleado de esta, Alberto, obligándolo a que le entregara la cantidad que se encon
traba en el mostrador de la sucursal,y pasó seguidamente a la habitación donde se hallaba
la caja fuerte, que estaba abierta. Allí se apoderó de más dinero, que sumado a la anterior
hicieron un total de S/ 3 9M 117.00. Tras salir de la entidad fue detenido por la Policía Na
cional del Perú. Dijo que lo hizo porque de no haberlo hecho él otra persona seguramente
lo hubiera realizado. Incluso antes que ingresara a la entidad bancaria observó a otros su
jetos también planeando el robo, lo que motivó que se apresurara en su ejecución.
Respecto al actuar de Isidro:
Hace referencia a los cursos causales hipotéticos, no siendo relevantes para el derecho penal.
Los cursos causales hipotéticos se refieren a las circunstancias que podrían haber llevado a un
resultado, pero que no tuvieron efecto. En este sentido, si Isidro menciona que otra persona
podría haber cometido el robo, esto no es relevante para la imputación penal, ya que no se
refiere a la acción efectiva que realizó Isidro.
Respecto el actuar de Isidro dentro de la imputación objetiva:
Creó el riesgo prohibido, riesgo que se mantuvo en el resultado, dentro del ámbito de acción
del tipo penal. Isidro creó un riesgo prohibido al robar la sucursal bancaria, y ese riesgo se
mantuvo en el resultado, lo que lo hace responsable penalmente por el delito cometido.
18. Miguel, como regla de vida, había decidido no usar los puentes peatonales. Cuando
retornó a Lima, después de varios años, comunicó a sus familiares que continuaba con la
misma convicción: “prefiero correr que subir escaleras”. Cierto día, salió de casa y, fiel a sus
convicciones, optó por cruzar la carretera corriendo; sin embargo, no calculó bien la veloci
dad del autobús que era conducido por Javier y Miguel impacto en contra de este. Miguel
murió inmediatamente.
Los hechos antes descritos son un caso de imputación a la víctima.
En este caso se produjo la ruptura del nexo causal por fractura causal, por lo que, javier no
deberá pagar la reparación civil.
Del mismo criterio es la Corte Suprema de la República al señalar en el Recurso de Casación
N.° 431-2020 Huaura (Fj.7-9.) de fecha 11 de mayo de 2022: "En ese contexto, cabe anotar que
la ruptura del nexo causal resulta evidente de acuerdo con el análisis del informe pericial;
además, está demostrado que la propia víctima fue quien generó de form a determinante la
producción del daño (la denominada ruptura del nexo causal), de tal manera que, al no existir
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1408 of 1506 --

UBILEX
una relación necesaria de causa-efecto entre la conducta antijurídica y el daño causado a la
víctima, dicho comportamiento no generaría una obligación legal de indemnizar. Por último,
debe indicarse que en la sentencia de mérito no se ha solventado de manera adecuada la exis
tencia de los elementos requirentes en el ámbito de la reparación, como son: í) la conducta
antijurídica, ii) el daño causado, iii) la relación de causal idad y iv) el factor de atribución.”
19. Alberto exige el otorgamiento de su beneficio penitenciario de semilibertad, pero no
ha cumplido con pagar la reparación civil.
Es posible que se le otorgue el beneficio si es que garantiza formalmente su futuro cumpli
miento8
1. Erika dirigía un salón d e ___;n una zona exclusiva de h -,r -
como empleada Ana, aprendiz de cosmetología. Laura decidió someterse a un tratamien
to de micropigmentación en los labios, que le fue realizado por Ana, bajo la supervisión
directa de Erika quien era su jefa, sin que conste que se llevara a cabo con carácter previo
prueba alguna de sensibilidad respecto de Laura. Lamentablemente, el tratamiento apli
cado causó la muerte a Laura. Erika y Ana aplicaban los pigmentos en la creencia que eran
naturales, cuando en realidad tenían un componente químico dañino para la salud.
De tratarse de un delito imprudente,¿cuáles son los criterios subjetivos que este requiere?
Conocimiento y previsibilidad. Siendo la intervención de Erika y Ana como autoras en base al
sistema unitario de autor.
2. Pancho y Trinidad habían discutido con Oscar y Diana, increpándoles a estos con las
siguientes expresiones: “los vamos a matar, les vamos a meter dos puñaladas”. Óscar y
Diana quedaron atemorizados por las amenazas verbales de Pancho y Trinidad. En un mo
mento dado, Pancho se dirigió en actitud agresiva a Óscar portando un cuchillo en la mano
y haciendo el ademán de ir a clavárselo al cuello. Óscar consiguió esquivar el intento de
agresión, entablándose un forcejeo entre ambos. Mientras tenía lugar el intento de agre
sión y los dos sujetos estaban en pleno forcejeo, Trinidad estaba situada junto a la pared, e
incitaba a Pancho diciéndole “mátalo, mátalo”. Óscar logró finalmente huir.
En el caso de que Pancho haya dado muerte a Óscar:
Trinidad no es instigadora (No aumentó el riesgo prohibido).
