6, Ángel, de nacionalidad mexicana (financista) y los peruanos Ramiro, Max, Mardon, De
vora, Alberto, Walter y Beríha, integraron una empresa criminal dedicada al tráfico ilícito
de drogas» En el caso concreto su objetivo era exportar clorhidrato de cocaína de Perú a Mé
xico en listones de madera, donde se acondicionaría y ocultaría la droga. Ello se descubrió
a raíz de las investigaciones de inteligencia realizada por la DIRANDRO, con intervención
del fiscal El día de la operación policial, se intervinieron a Ramiroy Max, quienes estaban a
bordo de un auto negro. Se halló en el asiento posterior del vehículo cuatro cajas de cartón
blancas cerradas con cintas de embalaje.
¿Es aplicable la teoría de la autoría mediata por dominio de organización en el ámbito em
presarial?
