y la administración de la EOPNP y administrar mancomunadamente con el jefe del de
partamento de Economía y Finanzas los fondos asignados a la Escuela”. En ese mismo año,
la jefatura del Departamento de Economía y Finanzas de EOPNP, estaba a cargo del co
mandante Lisandro. A razón de que se realizó un proceso de adquisición de compra de 500
equipos de cómputo para le EOPNP, se observaron una serie de irregularidades en dicho
proceso de adjudicación y adquisición de computadoras por lo que se inició investigación
