p o d e r d e d e c is ió n y p a r t ic ip a r o n en el p ro c e s o d e a d ju d ic a c ió n y a d q u is ic ió n d e lo s e q u ip o s d e
c ó m p u t o s e r ía n c o n s id e r a d o s a u t o r e s d e l d e lito , y a q u e t o m a r o n d e c is io n e s q u e lle v a r o n a la
c o m is ió n d e l d e lito .
