1. HOMICIDIO
i .Al finalizar una partida de fútbol entre Sos clubes más emblemáticos de Lima, Hugo, Paco
y Luis, llenos de indignación por la derrota del equipo de sus amores, la participaron en
una pelea masiva con los hinchas del equipo contrario, “Unión Lima”, situación que se salió
de control a pesar de los esfuerzos denodados de los miembros de la Policía Nacional del
Perú. Como consecuencia de dicho suceso lamentable, los tres amigos causaron heridas
de bala por arma de fuego a otros hinchas, quienes fueron luego internados en el hospital,
siendo que una semana después los hinchas murieron
