con Lorena, de diecisiete (17) años, pero luego decidieron terminar; al parecer, la familia
de Lorena no aceptaba que sean pareja. Ambas acataron la situación. Si bien se siguieron
viendo, Lorena había optado por solo cultivar una amistad. Esta circunstancia confundía
a Valeria que no había renunciado a retomar su relación. En el mes de abril, señala Vale
ria, la invitó a su departamento a disfrutar una canción muy significativa para ambas; sin
embargo, Lorena se sintió incómoda con el momento, cortó la canción y quiso retirarse del
inmueble. Esto produjo grave frustración en Valeria, quien aprovechó un descuido de Lo
rena para coger un cuchillo de la cocina y clavárselo en la clavícula. Según declaraciones
