10. Pavel es un joven centroamericano de veinticinco (25) años que llegó a Lima en octubre
de 2022. Él tiene tatuajes en el cuerpo con imágenes de una pandilla mara de su país de
nominada ‘Clica 24''. Al llegar a Lima se alojó en la casa de su tía Mafalda quien le encargó
cuidar a su hijo Mauro de trece (13) años. Desde el primer momento Mauro se mostró im
presionado con los tatuajes de Pavel. Luego de diversas charlas entre ambos sobre los ta
tuajes y las prácticas pandilleras en Centroamérica, Mauro le expresó que quería realizar
se tatuajes similares y que quería pertenecer a la ‘Clica 24''. Pavel mostró anuencia y llevó a
Mauro a realizárselos en una sala de tatuajes clandestina de nefasta reputación sanitaria
en Lima, prometiéndole que hablaría con su líder para incorporarlo como aprendiz, pero
que, mientras no sea incorporado, no puede realizar ningún acto propio de la pandilla, ni
mucho menos actuar en nombre de ella.
