Al evaluar el comportamiento que tiene Pavel respecto a su sobrino Mauro. ¿Cuál de las si
guientes alternativas contiene un supuesto delictivo que es imputable penalmente a Pavel?
Exposición peligrosa de menor de edad, regulado en el artículo 125 del Código Penal. Así, la
conducta de Pavel se adecúa al tipo penal independientemente de si el líder pandillero acepta
o no la Incorporación de Mauro. Lo relevante es que Pavel realizó actos concretos para inducir
al menora participaren la pandilla.
