1. Gustavo observó a Mari bajarse de un taxi y dirigirse a su domicilio. Aprovechando que
ella abría su puerta, Gustavo fue detrás de ella e incluso le puso una mano por detrás de la
cintura. Cuando Mari corrió al ascensor Gustavo la cogió del brazo y la introdujo en él, po
niéndole una navaja en el cuello. Le exigió a Mari que se quitara el pantalón, e intentando
bajárselo el propio Gustavo sin llegar a conseguirlo ante la resistencia de Mari y el hecho de
ponerse en cuclillas. En ese forcejeo la tocó por encima del pantalón en la zona del pubis,
no pudiendo continuar su acción, pues en ese momento bajó en el otro ascensor contiguo
un vecino, ante lo cual Gustavo abandonó inmediatamente el lugar.
