2. Juan, quien es mayor de edad, se va a la discoteca con luces psicodélicas junto a sus ami
gos un fin de semana. Durante su estancia ahí, él conoce a María, quien solo tiene 13 años y
11 meses años; sin embargo, debido a su contextura física logra pasar por una chica mayor
de edad. Ambos empiezan a bailaryterminan aflorando sentimientos mutuos, así que de
ciden ir a un lugar privado para tener intimidad. Ambos amanecen juntos en un hotel y se
despiden para que cada uno vaya a su casa, intercambiando números para comunicarse
posteriormente. María llega a su casa y su mamá le increpa por no haber llegado a dormirá
la casa y le obliga a desvestirse para saber si ha dejado de ser virgen. Al observarla, se per
cata que estaba manchada y María le confiesa que ha conocido a un chico fabuloso y que
ambos están muy enamorados. La madre denuncia el hecho ante la policía por el delito
de violación sexual de menor de edad. La policía detiene a Juan y en sus descargos indica
que desconocía que tener intimidad con su pareja podría ser delito. Ello debido a que am
bos acordaron iniciar una relación sentimental desde la noche que durmieron juntosyque
todo fue con consentimiento de ambos.
