6. Rocío es una obstetra que trabaja en el consultorio de Manuel. Un determinado día, lle
ga Ana y le indica a la obstetra que siente mucho dolor en su zona vaginal cuando tiene
intimidad con su esposo. De hecho, en aquel momento presentaba un dolor intenso y re
quería una atención urgente. Ante ello, Rocío le indica que debe sacarse su ropa interior y
recostarse en la camilla de atención ginecológica para poder examinarla. De inmediato,
Rocío llama Manuel para que le ayude a examinar el caso. Luego de diez minutos de aten
ción médica, Manuel se da cuenta que Ana es una ex de hace muchos años que lo enga
ñó con su mejor amigo y decide vengarse convenciendo a Rocío para quedarse a solas con
Ana. Procede a tener acceso carnal con ella,ya que había sido dopada por Rocío para poder
realizarle una intervención un tanto dolorosa. Esto antes que Manuel ingresara a la sala
de análisis.
