10. Liliana y Zoila son directoras de la empresa “Altas Cumbres”. Ambas le piden un prés
tamo al Banco “El Capital” por 100 mil dólares americanos. Para ello, se ponen de acuerdo
con Juan Sotomayor, Gerente General del Banco, quien les dice que su empresa no califica
para obtener el préstamo solicitado, pues no tiene activos que respalden ese préstamo, sin
embargo, Juan les dice que él les puede prestar 150 mil dólares y de allí le tendrían que
dar a él, 50 mil dólares, sugiriéndoles que presenten una serie de documentos adulterados
para sustentar la procedencia del préstamo. Lilianay Zoila aceptan y reciben el préstamo.
Al cabo de unos meses el Banco es intervenido y liquidado por la SBS, pues el préstamo
recibido por Liliana y Zoila era muy elevado y puso en problemas la situación económica
del Banco.
L ilia n a y Z o ila so n c o a u t o r a s d e l d e lit o d e o b t e n c ió n f r a u d u le n t a d e c r é d it o s y J u a n S o t o m a y o r
es s u c ó m p lic e .
12. Koki acudió a un banco donde solicitó y le fue concedido un préstamo personal de
S/27,000.00, presentando para ello, entre otros documentos, tres boletas, una certifica
ción de haberes y una constancia de trabajo, documentos todos ellos falsos que habían
sido confeccionados por Ramón, empleado de Koki, con su ayuda. El préstamo fue ingre
sado a una cuenta corriente abierta en la citada sucursal a nombre de Koki, quien lo retiró
por ventanilla ese mismo día. Esta operación bancaria fue realizada del mismo modo en
otras tres entidades financieras. Al ser detenido, Ramón sostuvo en todo momento que
había realizado estos hechos por orden expresa de Koki.
