bió una solicitud de amistad del perfil de Facebook "Voley con diversión" —cuyo titular
fue identificado como Julio Espinal— este nombre atrajo la atención de la menor, por lo
que, aceptó la solicitud de amistad, recibió mensajes de texto de dicha cuenta, quien le
ofreció ganar la suma de 250 soles por tener relaciones sexuales con personas que él se
iba a encargar de conseguir, le indicó que era de la ciudad de Lima y que le conseguiría un
"joven" quien leibaa pagar dicha suma portener relaciones sexuales. La menor de precaria
condición económica y débil soporte familiar, situación que fue aprovechada por el impu
