de Nulidad N°i7§7-20i7/Cal!ao» 2018, fundamento 4.
La menor de iniciales A.B.C de 16 años, vivía con sus padres en la ciudad de Pucallpa, luego
se fue de la casa por las constantes peleas de sus padres y convivió con su enamorado; sin
embargo, ante los constantes problemas, regresó a vivir con sus padres. Cuando se dirigía
al mercado en su centro poblado, encontró un aviso de trabajo en un poste de luz, llamó al
número telefónico consignadoyle contestó Pepe Torres quien le explicó en qué consistía el
trabajo. Este la llamó dos veces más cuando la menor estaba en su casa y le dijo que tome
un taxi que la lleve a su local y que él se lo iba a pagar. Al llegar al local, empezó a trabajar
con el nombre de “Stefany”, tomó bebidas alcohólicas con un cliente y le dieron un tique
de S/10,00, pero se retiró sin cobrar. En el local encontró a otras menores quienes hacían
tomar a los clientes, se dejaban tocar el cuerpo y podían salirdel local con ellos, para lo cual
estos debían pagar en la caja.
