4 » Fausto y J o a q u ín deciden cometer un asalto y robo a la farmacia Kafarma, para lo cual
convencen a Luis (quien es menor de edad-15 años), para que los acompañe,y premunidos
de arma de fuego llevan a cabo el asalto, pero al salir se percata la policía y al iniciarse una
balacera, Luis queda herido, lográndose atrapar a F au sto y Jo aq u ín .
El F is c a l en el d ic t a m e n f in a l p o d rá p e d ir q u e a F a u sto y J o a q u ín les a u m e n t e n la p e n a h a s t a
u n t e rc io p o r e n c im a d e l m á x im o le g a l f ija d o e n el t ip o p e n a l.
5. José Vega es un jo v e n de 17 años que se encontraba en el frontis de la librería “Ven a
saber” por la Av. Marañón con la finalidad de c o m p ra r unos libros a modo de regalos que
se hacía a sí mismo porque al día siguiente cumpliría 18 años. Luego de realizar las com
pras y ubicándose en el paradero de autos para tomar el transporte público hacia su casa,
sintió que dos personas se acercaban corriendo hacia él; de inmediato volteó a mirar si su
sospecha era correcta. E fe c tiv a m e n te , a l d a rs e c u e n ta de que dos sujetos se acercaban con
el rostro cubierto se quedó pasmado, n o p u d ie n d o c o rre r presa del miedo. Los dos sujetos
lo arrinconaron hacia un mototaxi que estaba estacionado muy cerca, uno de ellos sacó
un arma y se la apuntó en el pecho; el otro le empezó a quitar sus pertenencias; después
de ello, ambos sujetos le increparon que se largase del lugar y que no los mirara porque le
iban a “meter plomo” profiriéndole palabras soeces.
Respecto al supuesto descrito, es correcto afirmar que:
Es d e t e r m in a n t e id e n t if ic a r a la p e r s o n a q u e p o r t a b a el a r m a , p a r a la a p lic a c ió n d e la a g r a v a n
te "a m a n o a r m a d a ”.
En el supuesto de que los sujetos hubieran empleado una réplica del arma de fuego que no
era funcional. ¿Se configura el delito de robo con agravante “a mano armada”?
N o , p o r q u e el e m p le o d e u n a r é p lic a d e l a r m a q u e no es f u n c io n a l no p o n e en rie s g o el b ie n
ju r íd ic o ‘v id a 1.
6. Jorge y dos amigos se encuentran con la posibilidad de sustraer un celular del bolso de
una señorita distraída y emprenden hacia ella. Deciden que Jorge será el que sustraiga el
bien, mientras que los dos amigos se reparten funciones de “vigilancia” y eventual “con
tención” ante una posible alerta de descubrimiento o captura. Finalmente, cuando se en
contraban en plena huida fueron capturados por efectivos policiales de la zona y llevados a
su Despacho para determinar su situación jurídica. Según el costo de mercado, el valor del
celular no supera los S/. 500 nuevos soles. ¿Los sujetos han cometido una falta o un delito?
J o rg e y s u s a m ig o s d e b e n s e r p r o c e s a d o s b a jo la im p u t a c ió n d e u n a f a lt a c o n t r a el p a t r im o n io
a t ít u lo d e c o a u to re s .
7. Diego es un joven de 23 años que se encuentra con depresión porque no logro seguir con
sus estudios universitarios,ya que es adicto a la heroína. Diego trabaja arreglando electro
domésticos y normalmente se encuentra en los mercados con un letrero en el cual ofrece
sus servicios a las personas que lo ven. Diego mediante ese trabajo gana dinero de manera
