y luego vende lo robado en el mercado de su distrito,
Un día de esos Diego, sediento de acceder a la droga de Sa cual es adicto, opta por recorrer
las calles de madrugada. Luego de varios minutos logra visualizar a un joven que se encon
traba saliendo de una fiesta y que tenía una mochila abultada. Diego se acercó al joven con
intención de despojarlo de sus pertenencias; sin embargo, el aspecto de Diego intimidó
al joven de inmediato y le entregó la mochila sin que Diego dijera nada. Solo gesticuló un
rostro agresivo. Luego, al revisar la mochila encontró dos computadoras portátiles y un ce
lular de última generación. Al día siguiente le vendió los objetos a su amigo David, quien
sospechó que eran de procedencia ilícita, pero no dijo nada por la cantidad de dinero que
ganaría con su reventa.
En cuanto a la actuación de Diego:
C o m e t ió el d e lit o d e ro b o . D ie g o se a c e r c ó a l jo v e n c o n in t e n c ió n d e d e s p o ja r lo d e s u s p e rte
n e n c ia s , lo q u e c o n f ig u r a u n ro bo .
En cuanto a la actuación de David:
C o m e t e el d e lit o d e r e c e p t a c ió n . D a v id a d q u ir ió lo s o b je t o s r o b a d o s p o r D ie g o y no d e n u n c ió
el d e lito , lo q u e c o n f ig u r a la re c e p t a c ió n .
8. María cuenta con un costoso equipo de laboratorio que adquirió hace mucho. Por temas
familiares, tuvo que realizar un viaje a la selva por algunos días. Antes del viaje, debido a
que vive sola, contrata a jesús para mantener todo el equipo en buenas condiciones mien
tras ella está de viaje. El contrato fue a título gratuito. Vale decir que jesús se obligó a cus
todiar, conservar y devolver los materiales. Afortunadamente para María los asuntos que
tenía que atender se solucionaron más rápido de lo que esperaba por lo que retornó un día
antes de lo programado. Es así como, al dirigirse al domicilio, la atiende juan, el primo de
jesús, quien le informa que este no se encuentra hace varios días en casa, y que el equipo
lo prestó a unos estudiantes que son amigos de este primo para que puedan realizar unas
prácticas en su instituto. Este primo había implorado y convencido a jesús que lo haga, ya
que era de suma urgencia, sin realizar otro acto relevante que coadyuve a dicho préstamo.
Por estos motivos, María decide denunciar a Leonardo.
Respecto al delito de apropiación ilícita es correcto señalar que:
Se c o n f ig u r a el d e lit o d e a p r o p ia c ió n ilíc it a si en r e a lid a d no se tra tó d e u n p r é s t a m o s in o d e
u n a c o m p r a v e n ta .
Respecto al delito de apropiación ilícita:
La c o n s u m a c ió n se p r o d u c e c u a n d o el a g e n t e se a p r o p ia d e f o r m a d e f in it iv a d e l b ie n o c u a n d o
h a c e u n u s o d e t e r m in a d o d e a q u e l. La c o n s u m a c ió n no r e q u ie r e n e c e s a r ia m e n t e la p o s e s ió n
d e f in it iv a d e l b ie n , s in o q u e el a g e n t e d e b e real iz a r a c to s d e d is p o s ic ió n o u n u so d e t e r m in a d o
s o b re el b ie n m u e b le .
