p o s e s ió n si es le g ít im a 11”.
i. FABRI SAC es una empresa industrial localizada en el departamento de Amazonas, de
dicada a la producción de veleros de uso particular. Para la fabricación de estos veleros se
emiten gases de dióxido de azufre al medio ambiente, los cuales en niveles elevados ge
neran contaminación ambiental. Ante la pronta temporada de veleros, muchos clientes se
acercaron a la empresa para solicitar su velero personalizado. Desafortunadamente, tenía
un stock limitado de los mismos, por lo que muchos de sus clientes no pudieron adquirir
uno. Para solucionar este inconveniente, Dante Roca, gerente de operaciones de la planta,
decide poner las máquinas a trabajar con mayor velocidad para incrementar la producción
de veleros. Como ya era de esperarse, las máquinas superaron la emisión de dióxido de
azufre por encima de los niveles legales permitidos, dando como resultado daños graves
en el ambiente como la afectación directa de 200 hectáreas de árboles, además de causar
la muerte de más de 5 mil aves que habitan por la zona, entre ellos guacamayos y loros.
Respecto a la responsabilidad penal, es correcto afirmar:
El g e re n te d e o p e r a c io n e s s e rá r e s p o n s a b le p e n a lm e n t e p o r el d e lit o d e c o n t a m in a c ió n a m
b ie n t a l p o r h a b e r c a u s a d o u n g ra v e d a ñ o a m b ie n t a l c o n t r a v in ie n d o la s le y e s a m b ie n t a le s .
C o n f o r m e a lo s h e c h o s s u s c it a d o s , en re la c ió n al d e lit o d e c o n t a m in a c ió n a m b ie n t a l, es d e
e x ig e n c ia o b lig a t o r ia la e v a c u a c ió n d e u n in f o r m e f u n d a m e n t a d o p o r e s c r it o p o r la a u t o r id a d
a m b ie n t a l a n te s q u e el M in is t e r io P ú b lic o p u e d a p r o n u n c ia r s e p o r el d e lito .
11 El Código Penal en su jurisprudencia. Caceta Jurídica. Primera edición. Mayo 2007. Primera reimpresión
