CASOS PRACTICOS DESARROLLADOS
2, El Ministerio del Ambiente detectó la presencia de mortandad de peces y turbidez de
las aguas en un arroyo, en el que desembocan los vertidos de una empresa “L” de la cual
Luchito es gerente y administrador único. El valor de oxígeno recogido en las muestras re
sultaba incompatible con la vida de los peces y los demás valores analizados suponían una
fuerte alteración de su hábitat, infringiendo lo dispuesto en Sa Ley y el Reglamento de Or
denación de Pesca Pluvial y de los Ecosistemas Acuáticos continentales. Los vertidos cau
saron la muerte de 20,526 truchas y otras especies en el medio acuático en que se produjo
el vertido, daños que fueron valorados en la cantidad de 15 millones de soles.
De acuerdo con la Ley N° 30424» modificada recientemente por la Ley N° 31740, la empresa
“L”:
N o se le a p lic a r ía la Ley N ° 30424, s in o el r é g im e n d e c o n s e c u e n c ia s a c c e s o r ia s p r e v is to e n el
a r t íc u lo 105 d e l C ó d ig o P e n a l.
En base a la imputación penal de persona jurídica.¿Cuál es la principal crítica contra el mo
delo de imputación de transferencia o vicarial?
Q u e a fe c ta el p r in c ip io d e c u lp a b ilid a d . Este m o d e lo d e im p u t a c ió n p e n a l, q u e se b a s a e n la
r e s p o n s a b ilid a d v ic a r ia o d e t r a n s f e r e n c ia , p u e d e lle v a r a la im p u t a c ió n p e n a l d e u n a p e r s o n a
ju r íd ic a s in q u e se h a y a d e m o s t r a d o q u e h a y a c o m e t id o u n d e lit o p ro p io , s in o q u e se h a c o m e
t id o p o r u n a g e n t e d e la e m p r e s a . Esto p u e d e v io la r el p r in c ip io d e c u lp a b ilid a d , q u e e s t a b le c e
q u e el d e lin c u e n t e d e b e s e r el q u e h a c o m e t id o el d e lit o y no a lg u ie n q u e s im p le m e n t e ha
s id o r e s p o n s a b le in d ire c to .
3. Pochita SAC es una empresa industrial localizada en Ucayali dedicada a la producción de
veleros de uso particular. La misma, durante la fabricación de estos, emite gases de dióxido
de azufre, los cuales en niveles elevados generan contaminación ambiental. Debido a que
se acerca la temporada de veleros, muchos clientes compraron diversos veleros. Lamen
tablemente, la empresa tenía un stock limitado de los mismos, por lo que muchos de sus
clientes no pudieron adquirir uno. Para solucionar este inconveniente, Alejandro David,
gerente de planta, ordena poner las máquinas a velocidad máxima sin dar cuenta docu
mental de la real producción de dióxido de azufre, para así lograr producir mayor merca
dería. Desgraciadamente, estas máquinas emitieron azufre por sobre los niveles legales
permitidos, dando como resultado daños graves, como afectaciones directas en 200 hectá
reas de árboles, además de causar la muerte de miles de aves.
¿Qué delito de contaminación, conforme al Código Penal, se habría cometido desde la em
presa Pochita SAC?
C o n t a m in a c ió n a m b ie n t a l.
No es una agravante en los casos de delitos de contaminación ambiental.
A f e c t a r re s e rv a s n a t u r a le s r e c o n o c id a s p o r el E sta d o .
