3. Juan es un hombre de 35 años, ingeniero civil de profesión, que, luego de haber asistido
a un centro de recreaciones con unos amigos del trabajo y haber disfrutado de una rica pa
rrillada e ingerir bebidas alcohólicas variadas y, en cantidades considerables, porque era el
cumpleaños de su jefe, decide conducir su vehículo en dirección a su domicilio, pero cuan
do llega a este, su esposa no le abre la cochera, porque estaba molesta con él, razón por la
cual, Juan estaciona su vehículo en la vereda de la calle. Situación que genera que deba
dormir en la calle. La policía, que justo pasaba por el lugar, al intervenirlo se da cuenta que
se encontraba en estado de ebriedad, pero a la vez dormido, al despertarlo le realizan la
prueba de alcoholemia, la misma que superó el límite permitido por ley.
¿ J u a n c o m e t ió la c o n d u c t a t íp ic a d e ! d e lit o d e c o n d u c c ió n en e s t a d o d e e b r ie d a d al m o m e n t o
d e s u in t e r v e n c ió n p o lic ia l?
N o r e a liz ó n in g u n a c o n d u c t a t íp ic a al n o g e n e r a r s e p e lig r o p a r a el b ie n ju r íd ic o p o r q u e al m o
m e n t o d e la in t e r v e n c ió n e s t a b a d o r m id o .
