OS DESARROLLADOS
1. QUÍMICOS S.A.C es una empresa dedicada al rubro de comercialización de insumos quí
micos fiscalizados, siendo el ácido sulfúrico la sustancia que más rentabilidad le produce.
En el mes de noviembre de este año 2022, la empresa PRODUCE S.A.C, empresa industrial
dedicada a la refacción de motores, a través de su gerente de operaciones, Miriam Malea,
realiza un pedido de 12 000 litros de ácido sulfúrico. Al parecer, Joaquín Alcázar (miembro
de una organización criminal) concertó otorgar una suma de dinero a Miriam Malea para
que esta, aprovechando su puesto en PRODUCE S.A.C., pueda adquirir el ácido sulfúrico a
su favor, de tal forma que luego los colaboradores de Joaquín puedan recoger el insumo
químico. Y, en efecto, la transacción se realizó exitosamente. Después de pagar el pedido,
Joaquín Alcázar junto a sus compañeros de crimen se hicieron pasar por la empresa CAR
GO ENTREGA S.A.C., para recoger los 12 000 litros de ácido sulfúrico. Fue así como lograron
acceder a la sustancia química tal como lo habían planeado, y finalmente, partieron rum
bo al VRAEM para seguir dedicándose a su oficio, que es la producción de PBC.
Respecto a los hechos narrados, es correcto afirmar que:
