4. Roxana padece un trastorno del comportamiento conocido como el Síndrome de As
perger. Como consecuencia de este problema, si bien es capaz de conducirse conforme a
las normas sociales y jurídicas, Roxana presenta deficiencias en la interacción social que
le impide establecer lazos de amistad con facilidad y como consecuencia, se aferra a los
pocos amigos que tiene, confiando totalmente en ellos. Esta situación es aprovechada por
Liliana, una de las pocas amigas que hizo Roxana en su nuevo barrio, quien la invita a reali
zar un viaje gratis por Europa. Antes de pasar el control de equipaje de mano, Liliana entre
ga a Roxana una vasija decorativa para que le ayude a trasladarla, sin embargo, la policía
descubre camuflado en el adorno 2 kilos de clorhidrato de cocaína de alta pureza. Liliana
desapareció de la escena y la única procesada es Roxana. ¿Al respecto, hay algún tipo de
responsabilidad en Roxana?
R o x a n a n o es r e s p o n s a b le p e n a lm e n t e p o r a u s e n c ia d e l t ip o s u b je t iv o 12; a u s e n c ia d e d o lo u
e rro r d e tip o .
5. Leonor fue detenida por miembros de la Policía Nacional en el Aeropuerto ]orge Chávez,
cuando procedente de Bogotá-Colombia portaba en el interior de su estómago 80 cuerpos
cilindricos que contenían 899.5 gr. de cocaína, destinados a su posterior venta y distribu
ción en el país. Leonor es madre de dos hijos menores de edad, uno de los cuales padece
una deformidad congénita que ha requerido distintas intervenciones médicas costosas.
Cuando tomó la decisión de transportar la droga se encontraba sometida a una situación
de penuria económica que la llevó a actuar para poder obtener medios económicos que
permitiesen su subsistencia y la de sus hijos menores.
¿Cuál de las modalidades del tráfico ilícito de drogas se habría configurado?
P r o m o c ió n , fa v o re c í m ie n t o o f a c ilit a c ió n . L e o n o r t r a n s p o r t ó la c o c a ín a d e s t in a d a a s u p o s te
r io r v e n t a y d is t r ib u c ió n en el p a ís, lo q u e im p lic a la p r o m o c ió n d e l t r á fic o ilíc it o d e d ro g a s .
¿Qué supuesto jurídico que elimine la posibilidad de responsabilidad penal existe en el
caso de Leonor?
N in g u n o . La c ir c u n s t a n c ia d e s e r m a d r e d e h ijo s m e n o r e s d e e d a d y e s t a r e n u n a s it u a c ió n d e
p e n u r ia e c o n ó m ic a no es u n s u p u e s t o q u e e x c lu y a la r e s p o n s a b ilid a d p e n a l. La r e s p o n s a b ili
d a d p e n a l se b a s a en la c o m is ió n d e l d e lito , no e n la s c ir c u n s t a n c ia s p e r s o n a le s d e l a c u s a d o .
