CASOS PRÁCTICOS DESARROLLADOS
1. DELITOS COMETIDOS POR POBUCOS
i . Un inversionista llamado Roberto Méndez se ve involucrado en un proceso judicial por
haber golpeado a su esposa, es procesado por agresión contra las mujeres; cuando llega
el caso a primera instancia, es condenado, y al apelar el caso sería resuelto por un Tribunal
Superior cuyo ponente es el magistrado Alonso Dianderas, debido a que tenía intención
que la decisión lo exima de responsabilidad, desea acceder y conocer a dicho magistrado,
pues había averiguado que su casa iba a ser embargada por falta de pago. Cuando revisa
sus contactos, se percata que Martin Acero, abogado y su amigo, también conocía al juez
Alonso, entonces lo contactó a efectos de que le haga llegar el ofrecimiento de dinero a
cambio de que la resolución le sea favorable. Martín Acero logra entrevistarse con el juez y
le hace llegar la petición de Roberto Méndez, habiendo acordado dicha situación, luego la
resolución se publica con decisión favorable a este.
En el caso concreto respecto de Alonso:
A lo n s o D ia n d e r a s d e b e s e r a c u s a d o p o r el d e lit o d e c o h e c h o p a s iv o e s p e c ífic o , c o n d u c t a t i
p if ic a d a en el a r t íc u lo 395 d e l C ó d ig o P e n a l q u e e s t a b le c e : “El Magistrado, Árbitro, Fiscal, Perito,
Miembro de Tribunal Administrativo o cualquier otro análogo a los anteriores que bajo cualquier moda
lidad acepte o reciba donativo, promesa o cualquier otra ventaja o beneficio, a sabiendas que es hecho con
el fin de influir o decidir en asunto sometido a su conocimiento o competencia, será reprimido con pena
privativa de libertad no menor de seis ni mayor de quince años e inhabilitación conforme a los incisos i y 2
del artículo 36 del Código Penal y con ciento ochenta a trescientos sesenta y cinco días-multa".
