10o Adolfo Cápac fue procesado por delito de Robo Agravado y el Fiscal en su acusación soli
citó que se le imponga quince años de pena privativa de libertad y cinco mil nuevos solies en
concepto de reparación civil. Al iniciar el juicio oral, luego que el Fiscal hiciera la piesemca-
ción del caso, el acusado solicitó conferenciar con el fiscal para llegar a un acuerdo sobre la
pena por lo que se suspendió brevemente la audiencia, Al reinícíarse la audiencia el Fiscal
comunicó que había llegado a un acuerdo con el acusado en virtud del cual solicita se le
imponga cuatro años de pena privativa de la libertad y dos mil nuevos soles por concepto
de reparación civil. En este caso,¿cómo debería resolver el Juez?
D e s a p r o b a r e l a c u e r d o p o r v io la r lo s p r in c ip io s d e le g a lid a d y p r o p o r c io n a lid a d .
