I El Fiscal puede aplicar como beneficio premial la confesión sincera y la condición de delin
cuente primario de Jorge.
14. Ante la denuncia de un litigante de que el secretario judicial de un Juzgado Penal le
solicitaba suma de dinero» para agilizar su proceso y luego de proporcionar el registro y
grabaciones de llamadas telefónicas, se realiza un operativo fiscal con la utilización bi
lletes impregnados de reactivos y debidamente registrado en audio y video; en el cual se
interviene al Secretario Judicial en el instante que recibió el dinero. Luego de formalizada
la investigación preparatoria, el servidor judicial no acepta haber solicitado el dinero al
litigante; y, advirtiéndose que dentro de los primeros treinta días de la formalización de
investigación preparatoria, se agotarán todas las diligencias, el Fiscal puede como meca
nismo de simplificación procesal, en este caso:
Solicitar la vía de proceso inmediato.
15. Carlos Mendiola, chofer de combi, soltero, 25 años. Luego de haber estado bebiendo
cerveza junto a amigos de su barrio, se despide de ellos a altas horas de la noche y se pone
al volante de su automóvil. Mientras manejaba es intervenido por la policía, quien, al no
tar su aliento alcohólico, lo conduce a que se practique dosaje etílico, resultando que tenía
1.20 gramos de alcohol en la sangre. Carlos Mendiola es denunciado porel Fiscal y puesto a
disposición del Juez de Turno. El Juez:
Luego de abrí r instrucción por el del ito de conducción en estado de ebriedad, sólo podrá dictar
mandato de comparecencia, debido a que la pena a imponerse por dicho delito no supera los
cuatro años de pena privativa de libertad.
16. El imputado fue hallado en posesión del arma de fuego cuando efectuaba disparos en
la vía pública, encontrándose en estado de ebriedad. Acreditó tener la licencia correspon
diente para portar el arma, se estableció la presencia de alcohol, así como aceptó haber
salido de una fiesta después de haber bebido diez botellas de cerveza con unos amigos y
que ante la celebración d e su equipo de fútbol no se le ocurrió mejor manera de celebrar
que efectuar disparos al aire. Corresponde:
Al tenertodos estos elementos en las diligencias preliminares proceder a formular acusación directa.
17. Juan (dieciocho años) y María (quince años), después de concurrirá una celebración Patro
nal, habiendo ingerido dos botellas de cerveza, María decidió retirarse a su casa, lo cual Juan
muy solicito se ofreció acompañarla, en el trayecto ambos dieron muestra del afecto que se
tenían, siendo que al pasar por el Hostal “Latidos del Corazón” ambos decidieron ingresar y
mantener de mutuo acuerdo relaciones sexuales. Al despertar, María se percata que se en
contraba desnuda,y que sus partes íntimas estaban con sangre, por lo que decide retirarse a
su domicilio dada la hora, siendo acompañado por Juan, quien se despide cariñosamente de
ella, dejándola cerca de su domicilio, María una vez dentro de su casa refiere ante la interro
gante de su madre por saber dónde estuvo, que fue víctima de violación por parte de Juan,
procediendo su progenitora a denunciar tal ilícito ante la Comisaria. Ante ello, es correcto
afirmar según lo señalado por el Tribunal Constitucional en la sentencia 00008-2012-PI-TC:
Que, la conducta desplegada porel Imputado no resultara sancionada penalmente, dado, que
en el presente casóse ha acreditado el consentimiento fehaciente y expreso, más no dudoso o
presunto por parte de la agraviada.
1450 BALOTARIO DESARROLLADO PARA LOS EXÁM ENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 1451 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
18. Desde enero de 2005 hasta diciembre de 2e¡©<5, «Marcelo K® ejerció ia función de Mi
nistro de Estado. Luego en el n o v ie m b r e de 2012 es denunciad© por el delito de peculado,
pues según se advierte de la denuncia los hechos están relacionados con el ejercido de sus
fundones. ¿Corresponde al exministro «Marcelo K» sujetarse a las reglas del proceso por
razón de la función pública?:
No, porque ya transcurrieron más 5 años desde que concluyó su mandato.
19. En una investigación formalizada por delito de peculado por extensión, en la que se
imputa a Juan Pérez haberse apropiado de la suma de S/. 10,000.00 Nuevos Soles que le
fuera entregado por FONCODES para la ejecución de una obra pública; recibido el Informe
Pericial Contable ordenado por el Ministerio Público, se advierte que éste concluye que el
monto supuestamente apropiado fue utilizado en el pago de mano de obra no calificada
para la ejecución de la obra. Entonces el Fiscal debe:
Solicitar ante el Juez de Investigación Preparatoria el Sobreseimiento de la causa.
20. En una intervención policial a una persona conduciendo su vehículo en estado de ebrie
dad, con 1.80 gramos de alcohol por litro de sangre, sin licencia de conducir, quien no se
presentó a nivel policial pese a estar debidamente citado; sin embargo, en sede fiscal, ad
mite su responsabilidad, señalando que anteriormente también ha sido detenido en las
mismas circunstancias, pero pide una última oportunidad; usted como Fiscal provincial
Penal, ¿que haría?.
Formalizaría denuncia penal por Peligro Común-Conducción de vehículo en estado de ebriedad,
por cuanto la aplicación del principio de Oportunidad es facultativa en estos casos, y dadas las
clrcunstanciasy el comportamiento del imputado en el proceso, no lo considera pertinente.
21. A 40 funcionarios del Gobierno regional se les inician diligencias preliminares por deli
to contra la Administración Pública. Para los estándares del Art. 342o3 del Código Procesal
Penal de 2004, se trataría de un proceso complejo. Según la casación N° 318-2011-LIMA, la
duración máxima de dichas diligencias preliminares sería de:
1 2 0 d ía s .
22. El fiscal G tiene a su cargo el proceso de violación sexual en agravio de dos menores de
10 y 12 años cuya identidad está reservada, luego de dar por concluida la etapa de investi
gación preparatoria, comunica al juez y a las partes esta disposición, y procede a elaborar
el requerimiento de acusación. En relación al dictamen e informe pericial practicado a las
menores de edad:
El fiscal ofrece la declaración del perito que elaboro el dictamen o Informe pericial para que
sea examinado y contra examinado como órgano de prueba.
23. Se solicitó en la etapa intermedia la tutela de derechos puesto que la grabación efectua
da en los pasillos del Ministerio de la Producción en la cual se observa a Castro entregando
el dinero a Pérez (servidor de dicho ministerio), puesto que no habría contado con la auto
rización del Juez de la Investigación Preparatoria. Cómo debe resolverse dicha solicitud:
Improcedente, puesto que las acciones de tutela no se interponen en la etapa intermedia.
24. “El ciudadano Jorge García denuncia ante la Fiscalía, que, en la vivienda ubicada frente
a la suya, diariamente, en horas de la noche, ingresan y salen hombres y mujeres, y que,
incluso, muchas de estas últimas, son menores de edad; presume el denunciante, que es
