falsificad© la firma suya y la de su esposa, Josefina Bustamante, en una minuta, cuya copía
la adjunta en su escrito, en la que, supuestamente, los esposos, aparecen vendiéndole el in
mueble de su propiedad ubicado en Los Unidos ¿129, La Victoria. Recibida la denuncia, el fis
cal dispone el inicio de las diligencias preliminares por el término de diez días”. Consideran
