26. El 20 de abril del año 2012, Marco fue condenado a dos años de pena privativa de liber
tad e inhabilitación por un año, habiendo interpuesto su recurso impugnatorio de apela
ción contra la sentencia. En el marco del NCPP corresponde lo siguiente:
La pena de inhabilitación se ejecuta una vez que la decisión judicial quede firme.
27. El Juez de Investigación Preparatoria de Lamas dictó mandato de prisión preventiva contra
Julián Castrejón Jiménez como presunto autor del delito de violación sexual de menor de edad
en agravio de la menor de iniciales U.CB.J. de 7 años, por el plazo de 9 meses. Transcurrido el
plazo de la prisión preventiva y sin requerimiento fiscal de prórroga, el imputado puede:
Solicitar su libertad procesal conforme a lo establecido en el Artículo 273odel Código Procesal
Penal por exceso de carcelería.
28. Representantes del Ministerio Público, en coordinación con una unidad especializa
da de la Policía Nacional, están efectuando las primeras pesquisas, para identificar a los
miembros una organización dedicada al tráfico ilícito de drogas, de envergadura interna
cional, a tal efecto han de realizar los siguientes actos de investigación.
Circulación y entrega vigilada de bienes delictivos, agente encubierto y videovigilancia.
29. Una adolescente de 15 años viene siendo violada sexuaímente por su padrastro, los
hechos ocurren en casa, de manera sistemática y en circunstancias en que la madre de la
menor sale a trabajar de madrugada. La madre de la víctima se resiste a creer lo señalado
por ésta, es por ello por lo que no hace nada por esclarecer los hechos. El padrastro ha ame
nazado de muerte a la menor a fin de que no cuente a nadie acerca de los hechos. Sin em
bargo, la profesora del colegio ha notado la tristeza de la niña y advierte que hay indicios
de violencia sexual que ameritan sean denunciados.
Cualquier ciudadano puede presentar la denuncia penal a fin de que los hechos se Investi
guen, se esclarezcan y se sancionen debidamente.
