la Policía Nacional del Perú. Sobre si es posible que los familiares de Mamertino pongan
oficialmente en conocimiento este hecho ante la autoridad policial, en lugar de hacerlo
ante la Fiscalía, en el marco del Código Procesal Penal de 2004» es correcto afirmar que la
Policía:
Puede tom ar conocimiento del hecho delictivo, dar cuenta inmediata al Fiscal y realizar d ili
gencias de urgencia e imprescindibles en tanto no reciba otras instrucciones.
34. Las cámaras de vigilancia de la Municipalidad de Surco, registraron a Pedro López hur
tando las carteras de las transeúntes por las inmediaciones de la Avenida Tomas Marsano.
María fue una de sus víctimas, quien presenta su denuncia 12 horas después de haber su
frido la sustracción de sus bienes, habiendo identificado plenamente a Pedro López como
el presunto autor del hurto en su agravio. Al respecto corresponde:
La policía puede proceder a la detención de Pedro López al no haber transcurrido 24 horas de
ocurrido el hecho ilícito.
