chivó definitivamente la denuncia, ante esa situación se impugnará la decisión,¿Cuál es el
plazo previsto en el NCPP?
El Alcalde Provincial del Callao, al ser el agraviado, tiene 5 días para impugnar la disposición
fiscal.
