38. Patricio, ciudadano chileno participa de un robo agravado con arma de fuego en una po
llería y es atrapado por la policía nacional minutos después de cometido el atraco con el dine
ro robado de la pollería. Luego de las investigaciones preliminares el Fiscal Provincial penal
de tumo solícita la prisión preventiva contra Patricio al Juzgado de Investigación Preparato
ria. Respecto de la Prisión Preventiva solicitada por el Fiscal puede afirmarse que:
Es una medida de coerción personal orientado a conseguir o asegurar la presencia del im puta
do en el proceso cuando se presentan los presupuestos establecidos en el Artículo 268o del Có
digo Procesal Penal en concordancia con los Artículos 2ó9°y 270o del mismo cuerpo de leyes.
39. El ciudadano A es hallado muerto frente a la Plaza Dos de Mayo, presenta en el cuerpo
heridas de arma de fuego, luego de perennizada y protegida la escena del crimen, llega el
fiscal acompañado del Médico Legista y personal de criminalística, terminado luego el le
vantamiento del cadáver y de la escena conforme al procedimiento establecido por ley, el
cadáver es trasladado a la Morgue Central de Lima para la necropsia respectiva, durante el
procedimiento, se halló en los pulmonesy estómago del cadáver 2 proyectiles calibre 9mm.
El fiscal debe elaborar el acta fiscal de necropsia, consignando la cantidad, medida, peso, ca
racterísticas, peculiaridades de los proyectiles y serán entregados de inmediato a la pesquisa,
quien los remitirá con la cadena de custodia al Laboratorio de Criminalística del Instituto de
Medicina Legal y Ciencias Forenses del Ministerio Público para los exámenes respectivos.
