mó le fueron robadas por Luciano. Luciano desea traer como testigo a Hilda, en el juicio de
apelación, que se hará en el marco del Código Procesal Penal de 2004. Es correcto decir que:
Luciano puede ofrecer como testigo a Hilda si él ya la hubiese ofrecido en primera instancia,
pero Hilda no pudo acudir a la audlenciay no había declaración previa de ella, que pudo ha
berse leído en sustitución.
43- En la aldea de Huaco Seco, Mamertino ha sido víctima de un aparente homicidio, y sus
familiares hallan el cadáver. En Huaco Seco no hay Fiscalía, pero sí un Destacamento de
la Policía Nacional del Perú. Sobre síes posible que los familiares de Mamertino pongan
oficialmente en conocimiento este hecho ante la autoridad policial, en lugar de hacerlo
ante la Fiscalía, en el marco de la Ley N° 27934, es correcto afirmar que la Policía Nacional:
Puede tom ar conocimiento del hecho delictivo, dar cuenta inmediata al Fiscal y realizar d ili
gencias a que se refieren los 15 Incisos del art. i° de dicha Ley.
Con la modificatoria del art. 67 del CPP a través de la Ley N° 32130, pub. 10 ene.2024, la Policía
debe, Inclusive por propia Iniciativa, tomar conocimiento de los delitosy comunicar Inmedia
tamente al Fiscal, debiendo realizar, las diligencias de investigación urgentes o inaplazables
que formarán parte de las diligencias prellminaresy de la carpeta fiscal, para ¡mpedlrsus con
secuencias, individualizar a sus autores y partícipes, así como reunir y asegurar los elementos
de prueba que puedan servir para la aplicación de la ley penal.
4 4 . El 03 de abril de 2013, en horas de la noche, personal de serenazgo de la Municipalidad
de Chosica, interviene a Juan Orellana Pergamino, en circunstancia que éste se encontra
ba efectuando una sustracción violenta del bolso que tenía Ana Chichizola Benito, don
de la golpeó y amenazó con un arma de fuego. Inmediatamente dicho personal procede
a efectuar el registro levantando el acta de incautación y luego lo conduce a la Comisaría
de Chosica, juntamente con la agraviada. Acto seguido, la policía procede a recepcionar al
intervenido y elabora la Acta de Arresto Ciudadano adjuntando la Acta de registro e in
cautación a los actuados policiales. Señale usted lo que corresponde al procedimiento del
Arresto Ciudadano, según el nuevo Código Procesal Penal:
El personal de serenazgo no está facultado para elaborar un Acta de Registro personal e Incau
tación y que este sea agregado a los actuados policiales,ya que todo ello se hará constaren la
Acta de Arresto Ciudadano elaborada por la policía.
