48. "Roberto Belaunde» socio de la empresa Los Lucrativos Sociedad Anónima, denuncia,
ante el fiscal, que el Presidente de la empresa, Lucio Plasencia, en contubernio, con el con
tador, Ronald Vídaurre, ha falseado el balance contable de la sociedad, de los años 2011 y
2012, en la que han consignado perdidas inexistentes, con la finalidad de ocultar la apro
piación de las verdaderas utilidades. En su declaración, ante el fiscal, Roberto Belaunde,
además, proporciona copia de los libros contables, en los que se aprecian, los balances de
los años anteriores, 2009 y 2010, así como la declaración jurada de impuesto a la renta;
también se recibieron las declaraciones de los tres socios restantes, accionistas de la em
presa, quienes señalan que no se explican las ultimas perdidas que registra la empresa,
y advierten que los balances se vienen falseando”. Una medida proporcional que se debe
adoptar, como parte de la estrategia de investigación acorde a la naturaleza del delito, y
estando a que los denunciados han negado los hechos ante el fiscal, es la siguiente:
Inspeccionary, de ser el caso, asegurar la documentación contable de la empresa.
49. Carlos Ulloa Escobedo, Fiscal Provincial Penal de Moyo bamba, al leer el diario HOY se
topa con la noticia de que Gustavo Carpió Rojas, es denunciado por la madre de la menor
de inicíales R.A.A.C. de 10 años, como presunto autor del delito de violación sexual en agra
