Ordenara la policía se practique las diligencias preliminares o realizarlas por sí mismo.
52. Ante la intervención de una persona conduciendo su vehículo en estado de ebriedad,
con 0.51 gramos de alcohol por litro de sangre» conforme al Certificado de Dosajje Etílico»
quien acepta su responsabilidad en su manifestación policial, cuyo Atestado policial con
ios recaudos es remitido a la Fiscalía» usted como Fiscal Provincial Penal» ¿qué acciones to
maría?
Declararía Pertinente la Aplicación del Principio de Oportunidad y citaría al denunciado para
recibirsu consentimiento.
53. Luciano ha sido investigado, en el marco del Código Procesal Penal de 2004» por dos he
chos: [a] haber instalado defectuosamente una terma en la casa de Daniela, lo que generó
su muerte por electrocución y [b] haber dañado la red eléctrica en todo el barrio donde
vivía la difunta, debido a su pésima instalación. La calificación jurídica de estos hechos ha
sido: [1] homicidio culposo y [2] atentado contra la seguridad común (art. 281 °.i del CP» en
la forma culposa que autoriza el art. 282o). Cuando esta investigación pase a acusación, es
correcto establecer la siguiente relación.
Los hechos que se mencione en la acusación no pueden exceder a los dos hechos de la inves
tigación preparatoria ([a] y [b]).
54. Jorge Luis Pastor Polo, manejando su automóvil causa un accidente de tránsito don
de salió lesionada Esperanza Machuca Flores, quien según el reporte médico legal sufrió
de fracturas múltiples en los huesos de la tibia y peroné izquierdo necesitando 90 días de
atención facultativa por el mismo de tiempo de reposo. Iniciadas las investigaciones se
determinó que el vehículo que manejaba Jorge Luis figuraba a nombre de su padre don
Antonio Pastor Lezama, próspero empresario de la ciudad de Tarapoto. Ante esta situación
el Fiscal, para asegurar el pago de la reparación civil debe:
Incorporara Antonio Pastor Lezama como tercero civilmente responsable conforme a lo esta
blecido en los Artículos iii° y n z ° del Nuevo Código Procesal Penal.
55. Se considera a Pedro y Luis como presuntos responsables del delito de Tenencia Ilegal
de Armas, habiéndose efectuado dentro del proceso la incautación; pero esta no fue obje
to de confirmación judicial. Dicha diligencia se efectuó en flagrancia.
La falta de confirmación judicial no invalida su valor probatorio.
