57. Juan Pérez fue absuelto de los cargos de la acusación fiscal en primera instancia, luego
del recurso de apelación interpuesto por el Fiscal, fue condenado en la sentencia de vista,
sin que la defensa técnica o el imputado estuvieran presentes en la Audiencia de apela
ción. Al respecto cabe señalar:
Que la prueba adm itiday actuada en segunda instancia no fue sometida al contradictorio.
58. Juan Castro» miembro de la Policía Nacional» interviene a una persona involucrada en
un delito de hurto agravado. Según lo establece el Artículo 68° del Código Procesal Penal,
luego de tomar conocimiento del hecho punible y realizar la comunicación al Ministerio
Público, Juan Castro debe:
Continuar realizando las diligencias de urgencia e imprescindibles para impedir las conse
cuencias del delito.
59. La ciudadana X denuncia haber sido víctima de lesiones por parte de su vecina B, quien
en una fiesta patronal se abalanzó contra la denunciante a raíz de una discusión por la
venta de cerveza, dándole de golpes y puntapiés que le ocasionaron hematomas y exco
riaciones en el cuerpo, lesiones que arrojaron 12 días de incapacidad para el trabajo; hecho
que está acreditado con el Certificado Médico Legal, con las respectivas manifestaciones
de las partes y testigos del hecho.
Acude al acuerdo reparatorio para proponer un acuerdo entre las partes en conflicto.
60. Juan Auqui fue denunciado por haber dado muerte a su conviviente Carmen Campos, for
malizándose la investigación preparatoria el 05 de diciembre del 2007 en Huancayo, lugar
donde vivía Juan, no habiéndose encontrado el cuerpo de la víctima; no obstante en febrero
del 2009 se encontró el cuerpo de Carmen en Lima, lugar donde tuvieron su domicilio los con
vivientes, portal razón Juan deduce la nulidad de todo lo actuado, sosteniendo que el juez de
Huancayo era incompetente, en este caso el pedido de Juan debe ser declarado:
Improcedente ya que la incompetencia no acarrea la nulidad.
61. Ante los gritos producidos en un departamento, diversos vecinos llaman a miembros
del serenazgo y de la Policía, quienes luego de tocar el timbre, al escuchar que se mante
nían los gritos, ingresan al inmueble, donde encuentran a una dama y sus hijos con los ojos
llorosos, y, a un varón que se identificó como el esposo y dueño de la casa y quien pidió a los
miembros del serenazgo y de la Policía que se retiren de su domicilio. Frente a ello, la dama
y los hijos se retiran del inmueble y presentan una denuncia en la Comisaría por agresión
física. Posteriormente, a nivel del Ministerio Público, el Fiscal Provincial como el Fiscal Su
perior estiman no haber mérito para formular denuncia alguna por cuanto los vecinos no
concurrieron a ratificar la denuncia. Frente a ello, la dama, en nombre propio y el de sus
hijos presenta una demanda de amparo. Es correcto afirmar:
La demanda puede ser admitida para determinar si la decisión del Ministerio Público es arbi
traria o no.
C BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1459 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
Por cuanto la dama y sus hijos consideran que su denuncia no fue debidamente atendida y
buscan protección judicial ante una posible violación de sus derechos. En este sentido, la de
manda busca revisar la decisión del Ministerio Público y determinar si fue razonable o no, lo
que es un requisito fundamental para el ejercicio del derecho de amparo.
62. Pepe, jefe de la Dirección de Seguridad Ciudadana de la Policía Nacional del Perú, aler
tó en varias ocasiones a su amigo Beto, -también efectivo policial y dueño de una discoteca
donde trabajan ciudadanas colombianas i legalmente- antes de que la Brigada Especial de
Extranjería de la Policía llevara a cabo una inspección en la provincia. Pese al aviso de su ami
go, Beto finalmente no logró evitar dicha inspección, por lo que, como consecuencia de ella,
se le impuso a Beto una sanción administrativa. La fiscalía especializada también inició dili
gencias preliminares en su contra. Asimismo, a Beto se le abrió un expediente disciplinario.
En atención al presente caso, el Tribunal Constitucional en su reiterada jurisprudencia, ha
sostenido que:
El principio de tipicidad tiene protección en sede penal y administrativa.
Suponiendo que Pepe cometió un delito de infracción de deber impropio, es correcto in
formar:
El fundamento del mayor injusto penal es una agravante.
63. Cerca de las inmediaciones del Mercado Central de la Avenida Abancay en el Cercado de
Lima, se suscita una agresión física por parte de un vendedor ambulante de animales hacia
un transeúnte que comenzó a reclamarle verbalmente la actividad ilícita que venía desarro
llando. En vista que el agraviado sufrió una lesión por la cual perdió la consciencia en el acto,
los personas que presenciaron el hecho llamaron a los efectivos policiales que patrullaban la
zona, los mismo que, en cumplimiento de su función, proceden a intervenir a los implicados,
levantando un acta para registrar su identidad y el detalle de los hechos. Posteriormente, se
pone en conocimiento de la Fiscalía mediante un Informe Policial que contiene los antece
dentes que motivaron la intervención, las diligencias efectuadas, entre otros.
Respecto a la actuación policial:
La comunicación se debe dar por la vía más rápida, sin perjuicio de que se presente por escrito
indicando los elementos esenciales del hecho.
Respecto al informe policial:
Este será rem itido al Fiscal, se adjuntara la denuncia o antecedentes que motivaron la inter
vención, las diligencias efectuadas, las actas levantadas, las declaraciones recibidas, las peri
cias realizadas, los elementos materiales incautados y/o decomisados producto de la inves
tigación realizada, la comprobación del domicilio y los datos personales de los imputados, y
otros que la labor de investigación requiera (Art. 332.3 CPR modicado D. Legislativo N°i 605)
64. Cesar Carhuanta Valle fue detenido preliminarmente por causar lesiones graves a su
conviviente Lucia Veracruz Molina en medio de una discusión donde la lastimó con un ob
jeto punzo cortante a la altura de su brazo izquierdo. Previo al vencimiento del plazo, el fis
cal solicita al juez de investigación preparatoria la prisión preventiva contra el imputado
por el plazo de 9 meses, al cual luego de la audiencia correspondiente es declarada funda
da. Dos semanas antes del vencimiento de la medida, el abogado del imputado solicita la
cesación y sustitución por la medida de comparecencia, ya que considera que existen nue
vos elementos que demuestran que no concurren los elementos que motivaron su imposi-
