Respecto al plazo de la prisión preventiva solicitada por el fiscal:
No se tendrá en cuenta para el cómputo del plazo, el tiempo que la causa sufriere dilaciones
maliciosas atribulóles al Imputado o su defensa técnica.
Respectq a la decisión judicial:
El juez no puede ordenar la libertad del imputado, ya que no se habría vencido el plazo de la medida.
65. Por una denuncia de parte, la Segunda fiscalía provincial penal corporativa de Lima
abre investigación contra Walter Marino Díaz, por el delito de violación en agravio de su
compañera de trabajo Carmen Salinas Ochoa, quien alega que en una reunión laboral el
imputado le habría suministrado una droga que la adormeció para aprovecharse de su
estado dé inconsciencia. El sindicado se habría ofrecido a llevarla a su domicilio donde
posteriormente habría cometido el hecho ilícito, el cual fue advertido por la agraviada ya
que se levantó desnuda y con signos de haber sido sometida a acto sexual. Luego de las
pertinentes y exhaustivas diligencias preliminares correspondientes, la fiscalía conside
ra que no existen elementos de convicción suficientes para formalizar y continuar con la
investigación preparatoria y ordena el archivo de todo lo actuado. Ante ello, la agraviada
presenta su requerimiento de elevación de actuados en el plazo legal alegando que no se
ha cumplido con recabar la geolocalización del imputado para ubicarlo en el momento que
ocurrieron los hechos y solicita que la investigación sea reasignada a otro fiscal; una peti
ción que fue resuelta por el superior jerárquico que revocó la decisión de primera instan
cia, ordenando que otro fiscal provincial retome la investigación.
Respecto a la inexistencia de elementos de convicción y a la decisión de archivo:
No fue correcta, porque es una de las causales establecidas en el código procesal penal para
ordenar el archivo de las diligencias preliminares slemprey cuando se hayan agotado las d ili
gencias de Investigación, lo que no ocurrió.
Respecto a la decisión del superior jerárquico:
Sí fue correcta, porque se justifica que el fiscal superior designe a otro fiscal, cuando se de
muestra que la denuncia no fue debidamente investigada.
66. Juan, Marcos, Cecilia y Salvador, son servidores públicos del Poder Judicial de Cañete y
vienen siendo investigados por el delito de organización criminal, dedicada a cometer de
litos contra la administración pública en la modalidad de tráfico de influencias y cohecho.
En el transcurso de las investigaciones, el abogado defensor de Cecilia solicita que se le
permita a su patrocinada rendir su declaración, solicitud que es desestimada por la fiscalía
alegando que tal acto de investigación es un medio de prueba que no corresponde a un
acto urgente e inaplazable, por lo cual se programará oportunamente. Ante ello, el aboga
do defensor de Cecilia presenta una tutela de derechos, la cual es rechazada liminarmente
por el juez de investigación preparatoria al considerar que esta no es la vía procesal para
hacer valer sus derechos, ya que tiene una vía propia.
Respecto al derecho de declarar del imputado, marque la alternativa correcta:
El fiscal está obligado a recibir dicha declaración en cualquier etapay grado del proceso.
