6 7 . Considerando que la Alíela de derechos es «na acción procesal sasidua! esto es, opera
cuando el ordena míen io procesal no especifique el camino determinado para e! reclamo
pof un derecho afectado, es correcto afirmar:
El juez tiene la facultad de realizar un control de admisibilidad del contenido del pedido de
tutela de derechos-sin convocara audiencia-cuando el agravio pudiera tornarse irreparable.
La tutela de derechos es una acción procesal residual que se utiliza cuando el ordenamiento
procesal no especifica el camino determinado para reclamar un derecho afectado.
68. Bances enfrenta un juicio por el delito de violación sexual de un menor de 12 años. La
fiscalía solicitó en su requerimiento de acusación que se le imponga la pena de 30 años de
privación de la libertad. En el transcurso de la actuación de las pruebas en juicio el juez
dispone que, en primer lugar, se proceda con la oralizacíón de la prueba anticipada de de
claración en Cámara GesseS de la víctima, luego se actúen los medios de prueba admiti
dos como las declaraciones del denunciante -padre de la víctim a-y peritos; finalmente,
se proceda con el examen del acusado y la presentación de la prueba material. Respecto a
la oralizacíón de la prueba material, esta tuvo lugar en virtud de una solicitud fiscal en la
que se indicó Sos folios donde obra el acta de audiencia de prueba anticipada y el registro
de audio y vídeo de esta para su reproducción.
Respecto al orden y modalidad de! debate probatoiio:
El debate probatorio, debe seguir un orden establecido por la normal procesal, el cual inicia
con el examen del acusado. Esto garantiza que se cumplan los requisitos procesales y se ase
gure la imparcialidad del proceso.
Respecto al trámite de oralizacíón de los medios de prueba:
Ante la solicitud fiscal deoralización, le corresponde al fiscal destacar oral mente el significado
probatorio que considere útil. Esto permite que el fiscal explique claramente el valor proba
torio de los medios de prueba y facilita su comprensión para los demás actores del proceso.
69. Una vez concluido el debate probatorio en el juicio contra Rosa Álvarez Mejía por el de
lito de estafa en agravio de su compañero de trabajo Julio Oliva Martínez, el juez convoca
nuevamente a audiencia para la oralizacíón de los alegatos finales de las partes, donde
en primer lugar el fiscal expuso sus alegatos, luego la defensa de la acusada y, finalmen
te, se realizó la autodefensa. En este acto se presentó el agraviado, quien alegó problemas
personales por su tardanza y solicitó que de manera excepcional se le permita el uso de
la palabra, lo cual fue concedido por el Colegiado, alegando que el Código Procesal Penal
faculta su uso de la palabra aun cuando no haya intervenido en el proceso. Posteriormente,
el Colegiado comunicó que se retirarían a deliberar de forma inmediata la decisión final
del proceso. Después de diez días de cerrado el debate, el Colegiado emitió una sentencia
condenatoria contra la acusada imponiendo la pena y la reparación civil máxima solicita
das por la fiscalía, aun cuando no hubo mayoría en la deliberación.
Respecto al desarrollo de la discusión final del proceso:
La decisión judicial de perm itir que el agraviado haga uso de la palabra fue incorrecta, toda
vez que la normal procesal establece que en todos los casos la últim a palabra debe ser del
acusado.
BALOTAR 10 DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1462 of 1506 --

UBILEX
Respecto de la deliberación del Colegiado en el proceso:
La deliberación no debió extenderse más allá de dos días, aun cuando se suspenda por enfer
medad del juez, hasta un máximo de tres días. La deliberación del Colegiado debe realizarse
inmediatamente después de cerrado el debate y no debe extenderse más allá de dos días,
incluso si se suspende por enfermedad del juez, con un máximo de tres días.
70. La Fiscalía contra el crimen organizado solicita al juez de investigación preparatoria la
medida de allanamiento, descerraje, registro domiciliario, incautación y detención preli
minar contra siete integrantes de la organización criminal denominada “Señores del Sur”
dedicados al robo de autopartes, toda vez que producto de las investigaciones se ha reu
nido suficientes elementos que permitan inferir que en los domicilios se almacenaba sis
temáticamente los bienes robados. El juez de investigación preparatoria declara fundada
la solicitud y establece que la misma deberá cumplirse en un plazo no mayor de diez días.
Respecto al requerimiento de allanamiento:
Esta procede siempre que sea previsible que se le negará al Fiscal el ingreso en acto de función
a un determinado recinto.
El allanamiento es una medida de investigación que se puede ordenar cuando se tiene m oti
vos razonables para creer que en un recinto específico se encuentran objetos o documentos
relevantes para el proceso. En este caso, el Fiscalía contra el crimen organizado solicitó el alla
namiento porque se cree que en los domicilios de los integrantes de la organización criminal
se almacenaban bienes robados. La medida de allanamiento se puede ordenar siempre que
sea previsible que se le negará al Fiscal el ingreso en acto de función a un determinado recinto.
Respecto a la duración de la medida:
Según el Protocolo de actuación conjunta, la autorización judicial tendrá una duración máxi
ma de dos semanas.
La duración de las medida de allanamiento, descerraje, registro domiciliario, incautación y de
tención preliminar es de diez días, como establece el juez de investigación preparatoria. Esta
duración es razonable para permitir que la Fiscalía realice las investigaciones necesarias sin
afectar excesivamente los derechos de los imputados.
71. José, joven universitario, se desplazaba por la calle San Agustín, aproximadamente a
las ocho de la noche, portando una mochila, en la que llevaba una computadora portátil.
En ese momento Andrés y Jorge aparecen de manera rauda, en una moto lineal, de donde
desciende este último, quien premunido de un arma de fuego amenaza a José y le exige
que le entregue sus cosas. Sin oponer resistencia el agraviado accede a ello. En tanto los
malhechores estaban huyendo, a unos cien metros de distancia la moto lineal en la que se
desplazaban colisiona con un automóvil que pasaba por la zona, quedando mal heridos,
momento oportuno en el que aparece una unidad del serenazgo y miembros de la PNR
Entonces, uno de los supuestos porel que procede el proceso penal inmediato (art. 446° del
CPP), es el de flagrancia delictiva y está sujeta:
Respecto a los tipos de flagrancia delictiva que señala la Ley procesal, estas son:
a. Cuando el agente es descubierto en la realización del hecho punible.
b. Cuando el agente acaba de cometer el hecho punible y es detenido.
c. Cuando el agente ha huido y ha sido identificado durante o inmediatamente después de
la perpetración del hecho punible.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1463 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
d. Cuando el agente es encontrado dentro de las 24 horas después de la perpetración de
delito con efectos o instrumentos procedentes de aquel.
En el caso de josé, se configura la flagrancia delictiva porque Andrés y jorge, los autores del
delito, son descubiertos en la realización del hecho punible, es decir, en el momento en que
amenazan y roban a josé. Esto se ajusta a los supuestos de flagrancia delictiva establecidos
en el artículo 259 del Código Procesal Penal, que incluye la detención en flagrancia delictiva
cuando el agente es descubierto en la realización del hecho punible.
La flagrancia delictiva es un instrumento procesal que permite la detención inmediata del au
tor del delito, sin necesidad de mandato judicial, siemprey cuando se cumplan los supuestos
establecidos en la norma. En este caso, la detención se produce en el momento en que los
autores del delito están cometiendo el hecho punible, lo que configura la flagrancia delictiva.
Respecto al tipo de prueba vinculada a la flagrancia delictiva, esta es: Prueba di recta.
La flagrancia delictiva se vincula a la prueba directa. La flagrancia delictiva se configura cuando
se tiene evidencia sensorial directa de la comisión del delito, lo que permite una intervención
inmediatay urgente por parte de la policía. Esta prueba directa se basa en informaciones categó
ricas, procedentes del agraviado, de testigos o de filmaciones indubitables, que demuestran sin
necesidad de inferencias complejas que el detenido intervino en la comisión del delito.
72. Marioylulissa, quienes cursan el quinto año de secundaria, deciden no asistir al colegio
y, más bien, se van a un lugar desolado de la ciudad, momento en el que están abrazados.
Entonces se ven sorprendidos por un mototaxi color rojo, bajando de su interior Marcos y
Fercho, quienes cogotearon a las víctimas, apoderándose de sus celulares y huyendo del
lugar. Aproximadamente dos horas después, en otro lugar de la ciudad, son intervenidos,
cuando estaban robando a otra persona. Se encontraron en su poder los dos celulares de
los menores; y, además, en la diligencia de reconocimiento de persona en rueda, los agra
viados los identifican como aquellos sujetos que les robaron. Con las imágenes de las cá
maras de video vigilancia que se habían obtenido del lugar de los hechos, la Fiscalía formu
la el requerimiento de prisión preventiva.
Considerando el concepto de flagrancia delictiva para establecer el tipo de procedimiento
a seguir: ¿Qué tipo de interpretación legal se debe realizar?
La Interpretación amplia de la norma procesal penal.
Esto se debe a que los imputados fueron identificados poco después de cometido el delito, se
encontraron en su poderlos objetos robados, y fueron reconocidos por las víctimas. Por lo tan
to, al tratarse de un supuesto de flagrancia delictiva, aunque no sea en sentido estricto, corres
ponde aplicar un procedimiento especial y acelerado, como el proceso inmediato regulado en
el artículo 446 del Código Procesal Penal. Esto justifica una interpretación amplia del concepto
de flagrancia, que permita abarcar situaciones como la descrita, en las que, si bien no hay una
percepción directa del delito, existen suficientes elementos de convicción que permiten inferir
la comisión del hecho delictivo.
73. Mario es un padre de familia que siempre fue responsable en su hogar, por lo que de
acuerdo a sus posibilidades económicas siempre respondió por las necesidades de sus dos
menores hijos, Carlos y Agustina, pero debido a la separación con su pareja Carla, decidió
por venganza no pasar alimentos a sus hijos, dado que ella no regresaba con él. Cabe re
saltar que Carla era víctima de violencia, de manera reiterada, lo que era razón suficiente
para no retomar la relación. Luego de un tiempo, Mario es condenado por el delito de omi-
