S]ón a la a s i s t o ? ísm ifor. Según el m y 4 1 c° del GPP, este delito debe set incoado como
proceso inmediato debido a la propia con figuración típica del tipo pena!.
Para estableces un proceso penal inmediato por el delito de omisión a la asistencia fami
lias; se necesita de la concurrencia de determinados elementos, siendo w¡io de estos:
Se necesita cumplir con la evidencia delictiva y ausencia de complejidad del caso. Esto signi
