copilar pruebas, ya que la evidencia ya está disponible y suficiente para proceder con el juicio
(446 del CPC).
La evidencia delictiva en los procesos inmediatos no requiere:
Diligencias de averiguación ulterior.
74. Roberto es un Joven que sufre de enfermedades epilépticas. Asimismo» tiene una hija
de 3 años con Margaret» con quien está separado. Roberto cumple con ia pensión de su hija
de manera cabal; con la pandemia y la orden de restricción de salida por la declaración de
cuarentena ordenada por el gobierno» se quedó sin trabajo» además de infectarse de la CO-
¥ 10- 19; por tanto» se encontraba en muy mal estado de salud. Tuvo incluso que regresar a
la casa de su madre» quien estuvo a cargo de su tratamiento. Debido a todas esas dificulta
des, Roberto dejó de cumplir con la pensión de su hija, situación en que la menor perdió el
año escolar dado que estudiaba en un colegio particular y se enfermó por la tristeza de no
ver a su padre, a quien era muy apegada.
¿Roberto realizó la conducta típica del delito de omisión a la asistencia familiar?
No, porque no pudo cumplir con pasar alimentos debido a las circunstancias externas, por
