En este caso el Fiscal de la investigación puede aplicar el principio de oportunidady no incoar
proceso inmediato.
1. Un juez se encuentra ante un caso muy complejoytiene dificultad para impartir justicia
por deficiencia de la ley vigente. Señale la opción correcta:
El juez ante la deficiencia de la ley debe aplicar los principios generales del derecho y el dere
cho consuetudinario, conforme al artículo 139 inciso 8 de la Constitución.
2. Marisol Venturo se encuentra recluida en el Establecimiento Penal de Chorrillos cum
pliendo pena privativa de libertady ha venido gozando del beneficio de visita íntima; pero
una vez que se dio el Decreto Legislativo 927» le negaron el beneficio señalando que no les
corresponde a las internas por terrorismo, lo que era falso puesto que este Decreto, al con
trario, permitía beneficios para terrorismo. El derecho fundamental vulnerado sería:
Libre desarrollo de la personalidad.
Este derecho garantiza que las personas puedan desarrollar sus capacidades y potencialida
des sin restricciones arbitrarias o discriminatorias. En este caso, Marisol Venturo fue privada
de un beneficio que le permitía mantener una visita íntima, lo que afectó su capacidad para
desarrollarsu personalidady mantener relaciones humanas normales.
