CAS03 PRÁCTICOS DESARROLLADOS
3. Como sons''scusr] da de los ? oíos do 79ridalísmoy d eiiricwesida registrados su 2! norte del
país, producidos por las procesos ds grupos de trabajadores azucareros con erar ios a las
medidas legislativas tomadas respecto de la eliminación de las exoneraciones a las em
presas agroazucareras en Sas que el Estado tiene participación, el Gobierno-al amparo de
Sa normativa constitucional- ha decretado un estado de emergencia por sesenta días, y ha
dado cuenta de ello al Congreso.
En el Perú rige el modelo del contralor amplio. En consecuencia, el juez constitucional no pue
de cuestionar la declaratoria en sí, sino la razonabilidad y proporcionalidad de las medidas
tomadas a su amparo.
En el Perú, el modelo de contralor amplio establece que el juez no puede cuestionar la decisión
del poder ejecutivo de declarar un estado de emergencia, pero sí puede evaluar si las medidas
adoptadas en su marco son razonablesy proporcionales. Este modelo de contralorse basa en
la Constitución Política del Perú, específicamente en el artículo 137, que otorga al Presidente
de la República la facultad de declarar un estado de emergencia con acuerdo del Consejo de
Ministros. El juez constitucional solo puede examinar la razonabilidady proporcionalidad de
las medidas restrictivas tomadas durante el estado de emergencia, pero no puede cuestionar
la declaratoria en sí misma.
4. Cansados de ser víctimas de la inseguridad ciudadana, los pobladores de uno de los
sectores de un asentamiento humano de la zona norte de la capital han implantado un
sistema vigilancia y control consistente en varias rondas vecinales las 24 horas del día. Es
así como, dos días después de ocurrido el robo en una vivienda, lograron la captura de dos
individuos, a los que atribuyeron la comisión de dicho hecho. Luego de un “castigo ejem
plar”, y tres días después de haber sido capturados, dichos individuos fueron puestos a dis
posición de la Policía Nacional.
La restricción de la libertad personal por parte de un particular a otro se denomina “aprehen
sión”; y ella, en la lógica de la colaboración con la justicia, se entiende como una autorización,
mas no como una obligación legal para el ciudadano.
5. El congresista Leoncio T. C. ha sido denunciado por el delito de violación sexual en agra
vio de una joven que trabajaba como secretaria de su despacho congresal. El congresista
aludido ha exigido que se respete su foro parlamentario, por lo que ha pedido que la Sub
comisión de Acusaciones Constitucionales sea la encargada de ver su caso y decida, en su
oportunidad, la procedencia o no de la denuncia fiscal y posterior procesamiento penal.
Corresponde seguir un procedimiento de levantamiento de la inmunidad, al tratarse de un
delito de naturaleza común.
6. Una universidad local ha sancionado con la expulsión a un alumno por haber fumado
marihuana al interior de sus instalaciones. Sin embargo, en tanto que el reglamento disci
plinario no ha establecido qué sanción corresponde a cada tipo de falta, el Tribunal Consti
tucional ha declarado fundada la demanda interpuesta por el estudiante y ha ordenado su
reincorporación a dicho centro de estudios. Dentro del debate sobre la “constitucionaliza-
ción del Derecho”, es correcto afirmar que:
El juez constitucional puede cuestionar tanto la tipificación de una determinada conducta
como infracción disciplinaria, como el establecimiento de esa determinada conducta tipifica
da como infracción “muy grave”, “grave”, “leve” o "muy leve”.
