y. Ei Tribunal Constitucional es el órgano supremo de interpretación y control de la consti
tucional idad. Es autónomo e independiente de los demás órganos constitucionales. Se en
cuentra sometido solo a la Constitución y a su Ley Orgánica. Está integrado por (...) miem
bros, designados por el Congreso de la República, mediante (...):
7 miembros - Resolución Legislativa.
8 . El control judicial difuso de constitucionalidad de las normas legales es una competen
cia reconocida a todos los órganos jurisdiccionales para declarar inaplicable una ley, con
efectos particulares, en todos aquellos casos en los que aquella resulta manifiestamente
incompatible con la Constitución, tal como lo establece el art. 138 de la Norma Fundamen
tal. El control difuso es, entonces, un poder-deber del juez consustancial a la Constitución
del Estado Democrático y Social de Derecho; sin embargo, un juez no puede hacer control
difuso cuando:
La validez de las leyes o normas con rango de ley sometidas a control ha sido confirmada por
el Tribunal Constitucional en el seno de un control abstracto de constitucionalidad.
9. Al no lograr que Braulio desaloje el inmueble que viene ocupando el propietario decide
cortar los servicios de agua y luz a fin de lograr dicho fin. Sobre dicha medida corresponde
decir (STC N° 03668-20Q9-PA/TC):
La limitación o restricción de derechos no puede quedar en manos de particulares.
1. Conforme a lo establecido en el Artículo 122odel Nuevo Código Procesal Constitucional,
los organismos internacionales a los que puede recurrir cualquier persona que se conside
re lesionada en los derechos reconocidos por la Constitución, o los tratados sobre derechos
humanos ratificados por el Estado peruano, son:
El Comité de Derechos Humanos de las Naciones Unidas, la Comisión Interamericana de De
rechos Humanos de la Organización de Estados Americanos y aquellos otros que se constitu
yan en el futuro y quesean aprobados por tratados que obliguen al Perú.
Estos mecanismos internacionales brindan una instancia adicional de protección de los de
rechos fundamentales cuando se han agotado los recursos Internos en el país. Permiten que
las víctimas de violaciones de derechos humanos puedan presentar sus casos ante órganos
Internacionales independientes cuando consideren que la justicia nacional no les ha brindado
una reparación adecuada.
1. Jacinto Rodríguez interpone una demanda de amparo solicitando se le restituya la pro
piedad de un inmueble ubicado en la ciudad de Lima. Afirma, como fundamento de su
petitorio, que hace una semana el Estado inscribió en los Registros Públicos la propiedad
de dicho inmueble. Jacinto Rodríguez explica en su demanda que él es propietario del in
mueble desde hace cincuenta años, cuando lo adquirió de su anterior propietario, y que
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1467 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
nunca le transfirió su propiedad al Estado. Precisa» sin embargo» que su derecho de propie
dad sobre el inmueble no está inscrito en los Registros Públicos. En su escrito de demanda,
ofrece un conjunto de medios probatorios entre Sos cuales se encuentra: (i) la declaración
de 5 testigos; y (ii) una inspección judicial.
Si Usted es el juez Constitucional:
Rechaza liminarmente la demanda. Debido a que no se ha demostrado que la propiedad de
Jacinto Rodríguez haya sido violada ni que el Estado haya actuado de manera arbitraria. Por
lo tanto, rechazaría liminarmente la demanda y le pediría a Jacinto Rodríguez que agote los
recursos administrativos correspondientes antes de acudirá la justicia constitucional.
2. Tratándose de una demanda de amparo que fue declarada liminarmente improcedente,
decisión que se confirmó en segunda instancia, pero que el Tribunal Constitucional estima no
debió ser rechazada, corresponde a este órgano constitucional. Marque la opción correcta.
Revocar la decisión de segunda instancia y resolver la pretensión de fondo cuando se cuente
con los elementos suficientes para elloy la parte demandada haya tenido conocimiento de la
demanda.
3. En un proceso de amparo seguido por la Compañía Constructora BOD contra la Munici
palidad de la Rioja, la aludida compañía solicita medida cautelar con el objeto de dejar sin
efecto un acto administrativo emitido por el referido gobierno local. Ante tal situación el
Ministerio Público:
Interviene emitiendo opinión en el plazo de tres días.
4 . Carol Luz Sáenz Contreras ha interpuesto demanda de amparo contra el Servicio Na
cional de Adiestramiento de Trabajo Industrial (Senati), a fin de que se deje sin efecto la
Resolución Directoral N.° 042-2003/AL.DZLC que dispuso su expulsión por realizar actos
reñidos con la moral y las buenas costumbres. De dicha Resolución se advierte que la de
mandante fue sancionada con expulsión por haber sido sorprendida el día 23 de setiembre
de 2003 “[...] aproximadamente a las siete de la noche, en uno de los ambientes privados
del baño de damas del segundo piso del área de preprensa del SENATI, en compañía de
su enamorado Mario Alonso Mondragón Sánchez, a oscuras, sin responder al llamado de
la instructora Devora Huamán [...]. Lugar en el que estuvieron besándose [...]”; hecho que
constituye falta grave contemplada en el numeral 9 inciso e), del Manual de Conducta So
cial y Laboral de la Formación Profesional para Aprendices y Alumnos del Senati. Dentro
del debate sobre la “constitucionalización del Derecho”, es correcto afirmar que:
El juez constitucional puede cuestionar tanto la tipificación de una determinada conducta
como infracción disciplinaria, como la proporcionalidad en la aplicación de la sanción que ha
sido impuesta.
5. En segunda instancia se declara fundada una demanda de amparo interpuesta contra
una Municipalidad. El Procurador Municipal inicia un nuevo proceso de amparo contra lo
resuelto, al considerar que dicho fallo ha sido emitido desconociendo las competencias
administrativas de la Municipalidad establecidas en la Ley Orgánica de Municipalidades.
Al respecto es correcto afirmar que:
El amparo contra amparo tiene fuente directa en el segundo párrafo del artículo 200.2 de la
Constitución, pero en el presente caso no procede por cuanto no se invoca ningún agravio de
algún derecho fundamental de la Municipalidad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1468 of 1506 --

UBILEX
La Carta Magna establece que el amparo no procede contra resoluciones judiciales firmes dic
tadas con manifiesto agravio a la tutela procesal efectiva, que comprende el acceso a la justicia
y el debido proceso.
En el presente caso, el Procurador Municipal inicia un nuevo proceso de amparo contra lo
resuelto en segunda instancia, considerando que el fallo ha sido emitido desconociendo las
competencias administrativas de la Municipalidad establecidas en la Ley Orgánica de M uni
cipalidades. Sin embargo, no se invoca ningún agravio de algún derecho fundamental de la
Municipalidad, por lo que no se cumple con el requisito fundamental para la procedencia del
amparo cpntra amparo, que es la vulneración de un derecho fundamental.
6 . En un arbitraje de derecho se expide un laudo que declara Fundada la demanda. El de
mandado considera que en el curso del arbitraje se declaró indebidamente improcedente
su ofrecimiento de pruebas. Al respecto es correcto afirmar que:
Solo puede interponer recurso de anulación de Laudo, pues constituye una vía específica e
idónea, igualmente satisfactoria que torna improcedente el amparo.
Esta vía es la es apta para resolver la controversia en cuanto a la procedencia de las pruebas
ofrecidas durante el arbitraje. El amparo, por otro lado, es un mecanismo procesal constitucio
nal que se utiliza para proteger los derechos fundamentales y garantizar el acceso a la justicia.
No es una vía adecuada para resolver controversias sobre la procedencia de pruebas en un ar
bitraje de derecho. Por lo tanto, el demandado debe interponer recurso de anulación de laudo,
que es la vía procesal específica y idónea para resolver la controversia.
7. Raúl Martínez interpone demanda de amparo contra la empresa en la que trabaja. Soli
cita, como petitorio, que se deje sin efecto el acto mediante el cual se le despidió. Sostiene
que no incurrió en ninguna falta y que la razón de su despido es que pertenece a un partido
de una ideología contraria a la del partido al que pertenecen los miembros del Directorio
de la empresa. La empresa contesta la demanda y afirma que la causa del despido no tiene
ninguna vinculación con la identidad política del demandante. El Juzgado declara funda
da la demanda, pero no expresa ninguna motivación de la decisión adoptada. La empresa
interpone apelación y, resolviendo esta, la Sala Constitucional de la Corte Superior confir
ma la sentencia apelada. Contra la sentencia de segundo grado la empresa interpone re
curso de agravio constitucional.
El recurso de agravio constitucional interpuesto por la empresa debe ser:
Declarado improcedente. La empresa no puede interponer el recurso de agravio constitucio
nal porque no es el demandante original, sino la empresa que fue demandada. Además, la
sentencia de segundo grado ya ha sido confirmada, lo que significa que no hay una resolución
denegatoria que pueda ser objeto del recurso de agravio constitucional.
8 . Raquel Gómez trabajaba más de diez años en una empresa de productos de perfume
ría. Como su rendimiento fue satisfactorio, se le encargó la dirección de una división que
debía redoblar esfuerzos para aprovechar una temporada en la que la venta de los pro
ductos estaba creciendo. Sin embargo, Raquel le comunicó al Gerente de la empresa no
solo que no podía asumir la dirección aludida, sino que debía pedir licencia porque estaba
embarazada. Un día después, Raquel Gómez recibió una carta mediante la cual la empre
sa la despedía de su trabajo y le comunicaba, además, que había depositado en su cuenta
bancaria el monto correspondiente a la indemnización que por Ley le correspondía. Ante
I BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1469 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
esta circunstancia, Raquel Gómez interpone una demanda de amparo solicitando, como
petitorio, que se ordene su reposición en su centro de trabajo:
Si Usted es el Juez Constitucional:
Admite a trám ite la demanda, el derecho constitucional objeto de la demanda Interpuesta
por Raquel Gómez es el derecho a la remuneración.
1. Después de seguirse irregularmente el procedimiento de acusación constitucional, se le
abrió instrucción penal por los delitos contra la fe pública “falsedad genérica” y contra la
función jurisdiccional, por considerarse que, en su condición de Vocal Supremo Provisio
nal de la Sala Civil Permanente, actuó irregularmente en la tramitación y expedición de
la sentencia, en un proceso sobre pago de dólares e indemnización. Culminado el proceso,
el Vocal Supremo Instructor lo condenó por los delitos de fraude procesal, y contra la fe
pública, imponiéndole cinco años de pena privativa de la libertad, fijando el monto de la
reparación civil en la suma de cien mil nuevos soles. Al interponer su recurso de apelación,
la Sala Penal Suprema, confirmó la condena por los delitos de fraude procesal y falsedad
ideológica en agravio del Estado; y la revocó la pena impuesta, la que, reformándola, va
rió a tres años de pena privativa de la libertad, la cual fue suspendida, estableciéndose en
veinte mil nuevos soles el monto de la reparación civil. En el caso planteado, corresponde:
El proceso de Hábeas Corpus no tiene por objeto proteger en abstracto el derecho al debido
proceso.
2. El 19 de enero de 2011, la recurrente interpone demanda de Hábeas Corpus contra la Juez
del Primer Juzgado Especializado en lo Civil de Pasco y los vocales integrantes de la Sala
Mixta de la Corte Superior de Justicia de Pasco, con el objeto de que se declare la nulidad
de la Resolución de fecha 22 de julio de 2009, así como de su confirmatoria por Resolu
ción de fecha 08 de enero de 2012, a través de los cuales fue condenada por los delitos de
falsificación de documento y uso de documento público a 3 años de pena privativa de la
libertad, suspendida en su ejecución (Expediente N.° 2007-00555-0-2901-)R-PE-i). Afirma
que ha sido condenada pese a que no existe una conducta típica que encuadre el hecho en
la norma legal establecida.
Corresponde declarar improcedente el Hábeas Corpus puesto que no es competencia de la
justicia constitucional el determinar la subsunción de la conducta del procesado en determ i
nado tipo penal.
3. Un ciudadano plantea una querella por delitos de injuria y difamación contra dos ma
gistrados del Tribunal Constitucional por el contenido de los votos que emitieron en una
causa de Hábeas Corpus. En dicho proceso constitucional, los referidos magistrados seña
laron en su voto singular que dicho querellante debía abstenerse de seguir restringiendo
de modo abusivo la libertad personal del agraviado. Como la querella ha llegado a la Corte
Suprema, por el rango que ostentan los magistrados del Tribunal Constitucional, es correc
to afirmar que:
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1470 of 1506 --

UBILEX
Los miembros del Tribunal Constitucional gozan de inm unidady de las mismas prerrogativas
de los congresistas, por lo que cuentan con inviolabilidad de votos y opiniones. Por lo tanto,
carecen de responsabilidad penal por los votosy las opiniones emitidas.
4 Sandra Violeta Morales Hurtado presenta una demanda de Hábeas Corpus a favor de
Femando González León quien se encuentra internado en el penal de Huacho, puesto que
se ha dispuesto su haslado a un establecimiento penitenciario ubicado en 3uHaca, al res
pecto corresponde.
No constituye ninguna arbitrariedad si la decisión de la autoridad penitenciaria está debida-
mente sustentada.
5. Con fecha 6 de enero de 2009, don Miguel Palomino interpone demanda de Hábeas Cor
pus a su favor, y en beneficio de su esposa y sus menores hijos, y la dirige contra Pedro Pé
rez y María López, presídentey secretaria, respectivamente, de la Junta de Vecinos de! Par
que Loreto, sito en Sa calle N °i de ia urbanización Sol Villa, en el distrito de La Molina; así
como contra los vigilantes particulares Jaime Ramos y Ruperto Canchan, solicitando que
se disponga el retiro de las rejas que se han instalado en el referido parque y sus alrededo
res, donde se encuentra su domicilio, impidiendo el libre tránsito vehicular. El demandan
te aduce que él no quiso pagar una cuota mensual por el servicio de rejas para la seguridad
de todos los vecinos, porque no se encontraba de acuerdo con poner rejas alrededor de la
calle donde residía. Desde ese entonces, señala el demandante, los vigilantes le restringen
el libre tránsito de su vehículo por la calley además el mismo tiene que bajar para abrir por
completo la reja debido a que el personal de vigilancia no le brinda ni a él ni a su familia
dicho servicio. En el presente caso, usted como Juez Constitucional:
Debe declarar fundada en parte la demanda si existe una pardal restricción a la libertad de
tránsito, en este caso en el libre ingreso del vehículo del recurrente y de los miembros de su
familia, sin obstáculos, lo que se traduce en que el personal encargado de la seguridad frente
a las rejas no obstaculice el libre tránsito, por las vías respectivas, del demandante, sus fam i
liares y terceros. Sin que esto implique, el retirar las rejas de la calle.
6. Shelah Hoefken interpone demanda de Hábeas Corpus a favor de sus menores hijos
identificados con las siglas J.A.R.R.A. y V.R.R.A., contra Juan Manuel, padre de los meno
res, solicitando que en cumplimiento del régimen de visitas establecido por la resolución
judicial de fecha 29 de diciembre de 2006 y confirmado por la resolución judicial de fecha
6 de julio de 2007, se ordene al emplazado que les permita a sus menores hijos interactuar
con ella, toda vez que de manera reiterada les impide que puedan verla. El derecho funda
mental vulnerado es:
Derecho atener una familia.
7. Leoncio Hernández sostiene que el Fiscal formalizó denuncia en su contra por los delitos
de encubrimiento real, atentando contra los documentos que sirven de prueba en un pro
ceso^ supresión de documentos; cuando ya había prescrito la acción penal. El Juez Penal,
en mérito a la denuncia decidió abrir instrucción ordenando contra el imputado mandato
de detención. En este caso, el afectado plantea una demanda de habeas corpus preten
diendo que se deje sin efecto el auto de apertura de instrucción. Sobre dicha demanda
corresponde:
Considerar fundado el Hábeas Corpus conexo al afectarse el principio de legalidad y el dere
cho a ser juzgado en un plazo razonable.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1471 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
El habeas corpas es el proceso constitucional idóneo para proteger la libertad individual y ga
rantizar el acceso a la justicia en casos en los que se demuestre que se amenaza o vulnera la li
bertad. En este caso, la detención ordenada por el juez Penal sin que se haya cumplido el plazo
de prescripción de la acción penal y sin que se haya demostrado la existencia de un delito, viola
el derecho a la libertad individual y el derecho a ser juzgado en un plazo razonable.
8 . Juana (13 años» estudiante de tercer grado de secundaria]/ con buenas notas) participó
del robo de una cartera en un taxi razón por Sa cual fue sometida a un proceso de menor
infractor, en el que el Juez dispone que la adolescente cumpla con la medida de interna-
miento preventivo en el Centro Juvenil Santa Margarita de la ciudad de Lima, cuando está
demostrado que tiene su domicilio en la ciudad de Trujíüo» el Juez aduce que la medida ha
sido impuesta de esta manera porque no existe en dicha ciudad un centro de internamien-
to para adolescentes mujeres. En este caso corresponde plantear.
Hábeas Corpus conexo.
El habeas corpus conexo es el proceso constitucional adecuado para proteger los derechos
fundamentales conexos a la libertad personal, como el derecho a ser juzgado en un plazo ra
zonable y a ser tratado con dignidad. En este caso, el habeas corpus conexo busca proteger el
derecho de juana a no ser sometida a una medida de internamiento preventivo en un lugar
distinto de su domicilio, sin que se haya demostrado que no exista un centro de internamiento
para adolescentes mujeres en Trujillo.
9. Moisés y Maruja consideran que se les ha afectado su derecho a la prueba y la defensa,
porque ofrecieron declaraciones testimoniales que no fueron admitidas ni rechazadas por
el Juez. Con dichas testimoniales pretendían acreditar que desconocían el carácter ilícito
de su conducta (publicaciones difamatorias) puesto que el asesor legal de la empresa de
radio difusión en la cual trabajan, les dijo que sus acciones no afectaban ningún derecho.
Los dos se encuentran afectados en su libertad. El Hábeas Corpus que debe plantearse es:
Hábeas Corpus Conexo.
10. Michelle Messina interpone demanda de Hábeas Corpus y la dirige contra el Juez del
Cuarto Juzgado Penal Especializado en Delitos de Tráfico Ilícito de Drogas, la Fiscal de la
Primera Fiscalía Superior en lo Penal del Callao, los vocales de la Primera Sala Penal del
Callao, los vocales de la Sala Penal Permanente de la Corte Suprema de Justicia de la Re
pública, por vulneración de sus derechos constitucionales a la defensa, al debido proceso,
legalidad y a la tutela jurisdiccional. Solicita se deje sin efecto la sentencia condenatoria
mediante la cual se le impuso una pena privativa de libertad de 25 años por la comisión de
delito de tráfico ilícito de drogas, así como su confirmatoria mediante ejecutoria suprema.
Refiere el recurrente que a pesar de ser de nacionalidad italiana no se le facilitó un intér
prete para ejercer su efectiva defensa en el proceso penal. Alega además que no se llevó
a cabo la ratificación de la pericia química de la sustancia incautada. Señale qué tipo de
Hábeas Corpus corresponde:
Hábeas Corpus Conexo.
11. La Asociación de Agricultores de San Pedro y San Pablo denuncian que los señores Ven-
tocilla Izquierdo instalaron una tranquera en la vía de acceso a los poblados del Sector Ca
beza de Vaca, y para permitirles el acceso cobran la suma de dos mil nuevos soles. Siendo
esta vía una servidumbre de paso. El tipo de hábeas corpus planteado sería:
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1472 of 1506 --

UBILEX
Hábeas Corpus Restringido. Los agricultores denuncian que se restringe su capacidad de des
plazarse libremente. Esto configura una restricción menor en la libertad física de los agriculto
res, lo que justifica la tutela del hábeas Corpus restringido.
12. Cuando decimos que se puede plantear una demanda de Hábeas Corpus pese a haber
cesado la amenaza o la violación de la libertad personal, se exige que tales situaciones no
se repitan en el futuro nos estamos refiriendo al Habeas Corpus de tipo:
Hábeas Corpus Innovativo. Este tipo de Hábeas Corpus busca garantizar que no se vuelvan a
producir situaciones que afecten la libertad personal, incluso después de que la violación o
amenaza haya cesado.
13. María Villegas ha interpuesto demanda de Hábeas Corpus a favor de su hermano, Genaro
Villegas, por la violación de sus derechos a la vida, al debido proceso, a la legítima defensa y a
la libertad individual. Solicita que se obligue al Estado peruano a devolver con vida a su her
mano o informar dónde se encuentran sus restos mortales, y la anulación del proceso penal
que se le siguió en el Fuero Militar, en el cual se le condenó, en ausencia, a cadena perpetua
por delito de traición a la patria. Refiere que el beneficiario de la presente demanda constitu
cional, que era estudiante de la Facultad de Ingeniería de Minas de la Universidad Nacional
de Piura, el día 2 de octubre de 1992 salió a trabajar, y que nunca más se le volvió ver. Para
el caso de una desaparición forzada, ¿qué tipo de Hábeas Corpus es el que debe plantearse?
Hábeas Corpus instructivo. Este tipo de Hábeas Corpus procede cuando no es posible ubicar
el paradero de una persona detenida-desaparecida y tiene como objetivo garantizar los de
rechos fundamentales de la víctima y sus familiares, incluyendo el derecho a la verdad y la
protección contra la desaparición forzada.
14. Juan Pérez ha sido condenado a veinte años de pena restrictiva de la libertad por el de
lito de terrorismo. Ha cumplido los primeros tres años en el penal de Piedras Gordas en
Lima. Sin embargo, como consecuencia de algunos incidentes ocurridos entre los internos
del pabellón en el que se encuentra este sentenciado, el INPE ha decidido su traslado, por
razones de seguridad, al establecimiento penitenciario de Yanamayo, en Puno. Frente a
ello, la familia de Juan Pérez ha interpuesto una demanda de Hábeas Corpus con la fina
lidad de revertir tal situación y pueda ser trasladado a un centro penitenciario a menor
altura sobre el nivel del mar. Se argumenta que la salud del recluso se encontraría resque
brajada portal cambio de altitud.
Hábeas Corpus correctivo. Esto se debe a que el traslado de Juan Pérez del penal de Piedras
Gordas a Yanamayo, en Puno, por razones de seguridad, puede ser considerado como una me
dida que agrava en forma ilegal o arbitraria las condiciones en que se cumple su pena privativa
de libertad, afectando su salud. El objetivo del Hábeas Corpus correctivo es corregir este trato
indebidoy garantizarque las condiciones de reclusión sean razonablesy proporcionales, pro
tegiendo los derechos fundamentales del recluso.
15. Ricardo Pérez es un historiador que se encuentra estudiando los hechos políticos del
pasado reciente en el Perú. Uno de estos hechos involucra a funcionarios que actualmente
se encuentran en el ejercicio del poder político. Por eso, con la finalidad de que Ricardo
Pérez concluya sus investigaciones, fue detenido y conducido al aeropuerto y subido a un
avión con destino a Argentina. En el Perú se supo de este destierro una semana después,
e inmediatamente se reunión un grupo de colegas de Ricardo Pérez para conversar acerca
de los medios que existían para lograr su regreso. Uno de ellos era Abogado y, con la apro-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1473 of 1506 --

CASOS PRÁCTICOS DESARROLLADOS
bación d e ios o tro s co leg as d e R ic a rd o P é re z, in te rp u s o un hábeas corpus en cu yo p e tito r io
se s o lic ita se o rd e n e a i P o d e r E je c u tiv o q u e a u to ric e el re g res o al p aís d e R ic a rd o P érez.
La d e m a n d a d e h á b e a s c o rp u s in te rp u e s ta :
Es fundada. Ricardo Pérez fue detenido y desterrado sin un proceso legal regular, violando
su derecho a la libertad personal y a la protección judicial. La detención y el destierro sin un
proceso legal regular configuran una violación flagrante de los derechos fundamentales de
Ricardo Pérez, lo que j ustifica la tutela del hábeas corpus para proteger su 11bertady garantizar
su regreso al país.
16. Antonio Rivas cometió un delito y fue condenado a purgar una condena de diez años de
prisión. En el establecimiento penal recibió un trato adecuado,y utilizó el tiempo para reali
zar estudios y trabajos eventuales. Cuando se cumplió su condena, estaba dispuesto a rein
sertarse en la sociedad y consideraba que se encontraba rehabilitado. Su abogado solicitó al
juez competente que ordenara su excarcelación. El juez expidió el o fic io a la autoridad peni
tenciaria. Sin embargo, después de la recepción de dicho oficio ya habían transcurrido cinco
meses, sin que Antonio Rivas fuera puesto en libertad. Ante ello, Fernando Gálvez, amigo
suyo, interpuso una demanda de hábeas corpus y, como petitorio, solicitó que se ordene a la
autoridad penitenciaria que ponga inmediatamente en libertad a Antonio Rivas.
La demanda interpuesta por Fernando Gálvez es:
Fundada.
Cuando se cumple la condena de un recluso y el juez competente ordena su excarcelación, la
autoridad penitenciaria tiene la obligación de ponerlo en libertad de manera Inmediata. El
hecho deque Antonio Rivas haya permanecido cinco meses más en prisión después de que se
expidió la orden de liberación constituye una privación arbitraria de su libertad personal, que
debe ser corregida mediante el hábeas corpus.
i. “Liliana Plasencia, con fecha 20 de mayo de 2012, solicita ante el Jefe de la Oficina de Con
trol de la Magistratura de la Corte Superior de Justicia, la entrega de copias enumeradas
del expediente que contiene el procedimiento disciplinario seguido contra el juez, Amé-
rico Columbus, el cual había culminado en abril de 2012, con la confirmación de la sanción
suspensión por treinta días, que se le impuso; para tal efecto, adjunta, el recibo de los dere
chos respectivos previstos en el TUPA. Sin embargo, mediante una resolución de fecha 1 de
junio de 2012, el Jefe de la Oficina de Control, deniega el pedido, señalando que, en tanto
no ha sido parte en el proceso disciplinario, no le puede entregar las copias solicitadas”.
Ante esta respuesta, Liliana Plasencia decide incoar una acción constitucional; al respecto,
cuál de las siguientes, es la acción que debe formular:
Acción de Hábeas Data.
Esto se debe a que el hábeas data es el proceso constitucional que procede para acceder a in
formación que obre en poder de cualquier entidad pública, con las excepciones contempladas
en la ley, y para actualizar, incluir y suprimir o rectificar la información o datos referidos a la
persona del demandante que obren en entidades públicas o privadas.
