base d e los cuales Sos ju e c e s d e b e n id e n t if ic a r las normas que son objeto de control en los
procesos constitucionales d e acció n p o p u la r?
El 1 P L E N O JURISDICCIONAL EN M A T E R IA S C O N S T IT U C IO N A L Y C O N T E N C IO S O A D M I
N IS T R A T IV A publicado el 02.02.2016 acordó por unanimidad: 1. Un comunicado de una enti
dad pública puede ser objeto de control constitucional mediante el proceso de acción popular
siempre que se trate de una norma infralegal de carácter general que se incorpora al orde
namiento jurídico con vocación de permanencia. 2. Para identificar las normas -reglamentos,
normas administrativas, decretos y resoluciones de carácter general- que son objeto de con
trol en los procesos constitucionales de acción popular, y en consecuencia evaluar su proce
dencia, los jueces deberán observar los criterios de: (1) pertenencia al ordenamiento jurídico,
(2) consunción y (3) generalidad.
2. En el diario oficial “El Peruano” se ha publicado un Decreto Supremo expedido por el presiden
te de la República, concerniente al sector Economía y Finanzas. Esta norma establece las reglas
correspondientes a la elaboración del proyecto de Ley General de Presupuesto. Sin embargo, el
presidente de un partido político de oposición al gobierno está en contra del contenido de este
Decreto Supremo, porque le parece que las reglas aprobadas afectarán la eficiencia del proceso
de elaboración del referido proyecto de ley, actividad que se realiza anualmente. También ad-
viertequeel Decreto Supremo está firmado porel presidente de la República, pero noseencuen-
tra refrendado por ningún Ministro. Habiendo advertido este hecho, interpone una demanda de
Acción Populary, como petitorio, solicita se declare la Nulidad del Decreto Supremo.
Sí Usted es un ]uez Superior integrante de la Sala a cargo del proceso iniciado con la de
manda de Acción Popular, propondría a la Sala:
Que la declare fundada.
Esto se debe a que el Decreto Supremo no ha sido refrendado por ningún Ministro, lo que viola
el artículo 11.1. del Ley Orgánica del Poder Ejecutivo, que establece que los decretos supremos
deben ser firmados porel presidente de la Repúblicay refrendados porel Ministro del ramo res
pectivo. Esta falta de refrendo implica que el Decreto Supremo no tiene la autoridad necesaria
para ser considerado como una norma legal válida, por lo que su nulidad debe ser declarada.
