11. Cinco empresas, donde hay dos del mismo giro comercial, (empresa A y D) sin constituir
un consorcio deciden iniciar ante la Municipalidad Distrital de Surquillo en Lima el trámite
para la obtención de una licencia para la construcción y puesta en funcionamiento de un mo
derno centro comercial (Expediente 00 1 ). La empresa A advirtiendo que en el futuro puede
tener problemas de competencia comercial con la empresa D decide sin comunicarlo a las
demás empresas, desistírse del procedimiento iniciado. En dichas circunstancias la empresa
A decide agruparse con otras empresas que solicitaban igualmente una licencia para el fun
cionamiento de otro centro comercial aledaño a la zona y donde no había ninguna de su giro
comercial (Expediente 002). De acuerdo a nuestro ordenamiento administrativo el desisti
miento, existen dos niveles de desistimiento: uno es el desistimiento del procedimiento y el
otro el desistimiento de la pretensión. Sobre la base del contexto descrito precedentemente:
La administración municipal debe estimar el desistimiento en el Expediente 001 por cuanto
los efectos del desistimiento realizado sólo afectarán su situación jurídica en dicho expedien
te. En aplicación del artículo 189.1 de la Ley N° 2 7 4 4 4 . el desistimiento del procedimiento im
portará la culminación de este, pero no impedirá que posteriormente al administrado vuelva
a plantearse igual pretensión en otro procedimiento.
12. En materia de Derecho Administrativo, si un acto es realizado por un representante sin
facultades s u fic ie n te s ,¿ s e aplica el Principio de Informalidad?
La representación debe regirse estrictamente por el principio de Literalidady por ello el prin
cipio de Informalidad no es extensible ni aplicable a los actos de carácter estrictamente formal
que son parte de la estructura del procedimiento administrativo como el inicio del proceso y
la interposición de recursos impugnatorios.
