14'' El 15 de marzo de 201 o se inició un procedimiento administrativo sancionador contra un
administrado al haberse acreditado una infracción sancionable con 1 UIT, por lo que se le
sancionó el 15 de diciembre de 2010 con una multa de 1 UIT. Ante dicha situación el admi
nistrado interpuso recurso de reconsideración, el mismo que se encuentra en trámite. En
el supuesto que ayer haya sido publicada una nueva escala de sanciones que establece 0,5
UIT para la misma infracción, señale cuál de las siguientes opciones es correcta:
El principio de irretroactividad dispuesto en el Artículo 230.5 de la Ley N° 27444 se interpreta
del modo siguiente: si de manera posterior a la realización de una conducta tipificada como
infracción se produce una modificación de la norma que regulaba el supuesto, siendo la ley
vigente más beneficiosa para el administrado, se aplicará la nueva ley al caso en concreto a
pesar de no haber estado vigente en el momento en el que el administrado cometiera la in
fracción. Así, en este caso teniendo en consideración que el procedimiento se encuentra en
trámite y que la norma posterior es más favorable al administrado, corresponde reducir en la
etapa impugnativa la multa a 0,5 UIT.
15. En un operativo de oficio, la Oficina Regional del INDECOPI de Arequipa detecta que la
picantería LA ÑUSTA, de titularidad de Juan Robles no cuenta con libro de reclamaciones,
y le impone la multa de una UIT. Apenas notificado con la Resolución, Juan Robles inter
pone recurso de apelación, el que es resuelto por la Sala de Defensa de la Competencia de
INDECOPI, que confirma la decisión de primera instancia. Juan Robles considera que se
ha afectado su derecho a una resolución motivada, por lo que interpone demanda conten
ciosa administrativa ante la Sala Civil de la Corte Superior de Justicia del Arequipa. ¿Cómo
resolverá la Sala Superior?
La Sala debe adm itir la demanda pues es competente para conocer resoluciones que agotan
la vía administrativa en INDECOPI.
16. Martín Juárez es propietario del Restaurante Mí Barrio Fino, ubicado en el centro de
Lima. El día 12 de mayo del año en curso, la Municipalidad Metropolitana de Lima encon
tró que la cocina del local presentaba condiciones de insalubridad, también se detectó que
estaban guardando carne en descomposición y se encontró excremento de animales roe
dores alrededor de las ollas donde cocinaban.
Por estas faltas graves, Juan Juárez, funcionario de la Municipalidad Metropolitana de Lima,
encargado de llevar a cabo la fiscalización administrativa, decidió iniciar un proceso admi
nistrativo sancionador contra este negocio y dispuso como medida correctiva su clausura in
mediata hasta que regularice y subsane las infracciones administrativas detectadas.
¿De qué naturaleza es la medida impuesta por la Municipalidad de Lima?
Se trata de una medida de naturaleza correctiva.
Juan y Martín son primos, pero tienen una enemistad desde hace muchos años. Al respecto:
La enemistad de Martín y Juan constituye una causal de abstención de este en el proceso. La
abstención se refiere a la obligación de los funcionarios administrativos de abstenerse de par-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1480 of 1506 --

ticipar en un proceso cuando tienen un interés directo o indirecto en el resultado, o cuando
hay un conflicto de intereses. En este caso,ya que se ha demostrado que la enemistad entre los
primos afecta el proceso, no se puede considerar una causal de abstención.
17. El 01 ée diciembre de 2020, Ib Dirección de Supervisión del Organismo de Evaluación y
Fiscalización Ambienta! - OEFA realizó una supervisión regular a Pesquera Yakuy, con el
objeto de verificar el cumplimiento de las normas de protección y conservación del am
biente. Los resultados de la diligencia fueron consignados en el Acta de Supervisión con si
guientes hechos: Pese a que la pesquera cuenta con un compromiso am biental, por el que
se obligad veríes los efluentes industriales en su actividad fuera de la bahía de Pucusana,
vierte sus efluentes dentro de la bahía.
O E FA re s a ltó q u e la d es c a rg a d e e f lu e n te s sin t r a t a m ie n t o p re v io p o d ría g e n e r a r d añ o s
a m b ie n ta le s a c u m u la tiv o s so b re la f lo r a y f a u n a d e l m e d io , la cu al se e n c u e n tr a en proceso
d e r e c u p e a c ió n n a tu r a l. F re n te a es ta s itu a c ió n , d e s d e el d ía 15 d e a g o s to d e 2 0 2 0 P e s q u e
ra Yakuy c o m e n z ó a as r o ja r sus e flu e n te s in d u s tria le s fuera de la bahía, a una distancia tal
q u e no a fe c ta el m e d io m a rin o .
¿F¡ ente a qué tipo de infracción adm inistrativa nos encontramos?
Permanente. Esto se refiere a la descarga de efluentes industriales sin tratam iento previo, lo
que puede generar daños ambientales acumulativos sobre la flo ra y fauna del medio. Esta in
fracción no se lim ita a un momento específico, sino que es una conducta recurrente que puede
continuar generando efectos negativos en el medio ambiente.
¿Es posible llevar a cabo el inicio del Procedimiento Administrativo Sancionador o la con
ducta ya ha prescrito?
Sí es posible pues, de acuerdo con la Ley de Procedimiento Administrativo General, al ser una infrac
ción permanente, el cómputo del plazo de prescripción inicia desde el día en que cesó la acción. En
este caso, Pesquera Yakuy comenzó a arrojar sus efluentes industriales fuera de la bahía a partir del
15 de agosto de 2020, por lo que el plazo de prescripción no ha comenzado a correr aún.
1. Frida, que es administradora, t r a b a ja en la Gerencia de Ventas de la empresa del Estado PE-
T K O L IM A , Sa cual opera el oleoducto de la selva y la re fin e ría de Talara, entre otros activos que
son im p o s tan tes para producir petróleoy gasolina,y contribuir con el abastecimiento d e l país.
En el m e s de m a y o de 2021 la empresa LICSA, como todos los meses, adquirió grandes can
tidades de petróleo y gasolina a PETROLIMA para abastecer sus grifos que tiene a lo largo
d e l país. En e s ta oportunidad no realizó una transferencia por un monto de S/ 3,000,000
sin o e n tre g ó u n Cheque a Sa Gerencia de Ventas de P E T R O L IM A que fue recibido por Frida
q u ie n colocó en la fa c tu r a el sello de cancelado.
En a b ril d e 2 0 2 2 la C o n tra lo ría General de la República (CGR) ha iniciado una acción de con
trol en c o n tra d e Frida porque el Cheque de LICSA, entregado en mayo d e 2021, carecía de
fo n d o s ; no obstante, que LICSA regularizó el tema en julio de 2021.
¿Qué o p in a de la acción de c o n tro l interpuesta por la CGR?
Es procedente la acción de control. La CGR tiene la facultad de realizar controles y fiscalizacio
nes para garantizar el uso correcto de los recursos públicos y la transparencia en las operacio-
