2„ Debido a una s e rie de c o m p ra s extrañas realizadas p o r la Municipalidad d e S an Ju an d e
Miraflores, la Contraloría G e n e ra l de la R e p ú b lic a d e c id ió in ic ia r acciones d e c o n tro l p a ra
determinar si hubo un buen uso d e los recursos p ú b lic o s . Este p ro c e d im ie n to s es legítimo?
La autonomía que la Constitución Política del Estado establece para las municipalidades radi
ca en la facultad de ejercer actos de gobierno, administrativos y de administración, con suje
ción al ordenamiento jurídico. Por lo que, si bien la municipalidad es autónoma se encuentra
sujeta al Sistema Nacional de Control, aplicable a toda la Administración Pública.
3. La S u p e rin te n d e n c ia d e B ien es N a c io n a le s (§ B N ) ha convocado a s u b a s ta p ú b lic a p a ra
v e n d e r och o b ie n e s n a c io n a le s . Erizo,, q u e t ie n e el carg o d e M in is tr o d e E stad o , conoce b ie n
las c a ra c te rís tic a s d e d ic h o b ie n e s n a c io n a le s y e s tá in te re s a d o e n c o m p ra r c u a tro d e ello s ,
Para tal efecto, se pone de acuerdo con su amigo Adrián p a ra q u e él se p re s e n te a la subas
ta pública y pague el precio de c u a tro bienes nacionales.
Adrián se presenta a la subasta y oferta p o i los c u a tro b ie n e s n a c io n a le s y la SBN le otorga
la buena pro de dos bienes nacionales. Pasado algunos meses, Enzo re n u n c ia el c a rg o d e
Ministro de Estado y Adrián le v e n d e los dos bienes nacionales con un incremento del 5 %
del precio ofertado en la subasta.
¿Cómo describiría el caso planteado?
Se trata de un fraude a la ley. Enzo, como Ministro de Estado, conoce las características de los
bienes nacionalesy se pone de acuerdo con Adrián para que este último se presente a la subasta
públicayadquiera los bienes. Esto vaen contra de la disposición que refiereque los bienes nacio
nales deben ser vendidos a través de un proceso transparentey competitivo. Además, Adrián ob
tiene un beneficio económico al vender los bienes con un incremento del 5% del precio ofertado
en la subasta, loque es contrario a la intención de proteger el patrimonio nacional.
