UBILEX
¿Cómo debe pronunciarse el juez respecto a la reconvención?
El juez debe expedir resolución declarando que en esta vía no procede la reconvención.
Al tratarse de un caso que debe ser tram itado como proceso civil no procede la reconvención.
La reconvención es un recurso procesal que se utiliza en el ámbito del proceso contencioso ad
m in istrativo ^ en este caso, la Municipalidad de La Perla ha interpuesto una demanda conten
cioso administrativa contra la empresa Los Sauces S.A.y el Instituto Nacional de Defensa de la
Competenciay de la Protección de la Propiedad Intelectual (INDECOPI). Como lademandase
encuentra en el ámbito del proceso contencioso administrativo, no procede la reconvención,
que es un recurso procesal que se utiliza en el ámbito del proceso civil.
a
En el proceso contenciosos adm inistrativo Plena Jurisdicción se refiere:
A la tutela del derecho de las personas (administrados) y de ser el caso, se dictarán las medidas
preventivas, represivas, restitutorias y resarcitorias correspondientes contra los actos arbitra
rios de las entidades públicas.
2. ¿La figura de la prórroga de la competencia resulta aplicable a algunos supuestos del
proceso contencioso administrativo?
El I PLENO JURISDICCIONAL EN MATERIAS CONSTITUCIONAL Y CONTENCIOSO ADMINIS
TRATIVA publicado el 02.02.2016 acordó por unanimidad: Las reglas del proceso civil sobre la
prórroga de competencia son aplicables, en lo que resulten pertinentes, al proceso contencio
so administrativo, siempre que se trate de casos donde se pueda poner el riesgo los derechos
fundamentales de los justiciables a la tutela jurisdiccional que contiene el derecho de acceso
a los tribunales y para preservar sus derechos a la igualdady al debido proceso.
3. El servidor público J hosep Leyva quien viene afrontando dificultades económicas en el sos
tenimiento de su hogar, administrativamente es sancionado con una suspensión de 90 días
sin goce de haberes por la Administración. Ante su pedido de reconsideración, que expresa
mente es atendido favorablemente a los dos meses, la administración decide reincorporar
lo, al asumir que hubo una decisión incorrecta en la sanción impuesta y cumplida, pero no
atiende su pedido de pago de los dos meses que estuvo sancionado injustamente, esto es, se
atiende parcialmente su reconsideración. Ante ello el Señor Juan Vásquez considerando que
se le ha ocasionado daños y perjuicios, afectándose a su personayfamilia, decide acudir ante
el órgano jurisdiccional. Teniendo en consideración lo expuesto se puede afirmar:
Con el objeto de obtener una decisión favorable debe ¡nielar un proceso contencioso administrativo
de pago de la indemnización por el daño causado con la actuación impugnable, en forma acumu
lativa a la pretensión de la declaración de nulidad parcial o ineficacia de actos administrativos.
4. El plazo para demandar en la vía contenciosa administrativa: Los actos administrativos y
cualquier otra declaración administrativa. La actuación material que no se sustenta en acto
administrativo. La actuación material de ejecución de actos administrativos que transgrede
principios o normas del ordenamiento jurídico. Las actuaciones u omisiones de la adminis
tración pública respecto de la validez, eficacia, ejecución o interpretación de los contratos de
la administración pública, con excepción de los casos en que es obligatorio o se decida, con
forme a ley, someterá conciliación o arbitraje la controversia. Y las actuaciones administrati
vas sobre el personal dependiente al servicio de la administración pública.
Tres meses contando desde el conocimiento o notificación de la actuación impugnada, lo que
ocurra primero.
