UBILEX
De acuerdo a lo regulado en nuestro ordenamiento jurídico, la falta grave contiene los siguien
tes elementos:
El abandono de trabajo y las ausencias injustificadas son reiteradas. - La ausencia de Car
los configura una falta grave si existe dicho abandono por más de 03 días consecutivos, es
decir, 04 días de abandono de trabajo. Supuesto distinto es el de las ausencias injustifica
das, las cuales configuran también unacausal de despido, si Carlos se ausenta porel lapso
de 05 días en el periodo de 30 días calendario o, en el caso d e is días en un periodo de 180
días calendario, las cuales no tienen como requisitoel sersancionadas disciplinariamente
en su oportunidad; es decir, la norma no determina que el requisito para configurar el
despido sea el emplazamiento de amonestaciones escritas y suspensiones, sancionando
las ausencias de Carlos.
El trabajador no comunica o justifica el abandono de trabajo. - No es suficiente que el
Carlos abandone el trabajo, sino que además de dicha ausencia ésta no es puesta en co
nocimiento de su empleador, precisando cuales son las razones que la motivaron o que
ocasionaron dicho acto, generando así un incumplim iento en lo que respecta a sus obli
gaciones laborales.
El Reglamento de la Ley de Fomento del Empleo otorga a Carlos un plazo de 3 días hábiles
para que exponga las razones que ocasionaron el supuesto abandono, es decir, el comunicar
a través de cualquier medio, por lo que puede ser mediante llamadas, comunicación web, o
algún documento que acredite que Carlos puso en conocimiento de su empleador el motivo
de dichas ausencias. Es importante mencionaren este caso la reciente jurisprudencia emitida
por la Corte suprema en la Casación N.° 4548-2014.
