industriales, c o m e rc ía le s y m in e ra s . R esp ecto de las autorizaciones que requiere luán para
empezar a tr a b a ja r , es c o rre c to a f ir m a r que:
Requiere la autorización de sus padresy del Ministerio de Trabajo.
7. En el pro ceso ordinario laboral regulado por la N u e v a Ley P ro cesal del Trabajo, si el de
mandado no as iste a la audiencia de juzgamiento ¿Debe el juez actuar los medios proba
torios o fre c id o s a l c o n te s ta r la d e m a n d a ?
En el proceso ordinario laboral, el juez tiene el deber de actuar los medios probatorios do
cumentales que hayan sido ofrecidos por el demandado oportunamente de acuerdo con el
artículo 21o de la Nueva Ley Procesal del Trabajo, sin que se pueda imponer al demandado,
como consecuencia de su ausencia a la Audiencia de Juzgamiento, ninguna carga procesal que
no esté predeterminada expresamente por Ley. IV PLENO JURISDICCIONAL SUPREMO EN
MATERIAS L A B O R A L Y P R E V IS S O N A L T e m a i.Pub. 13.05.2016.
8. Un trabajador percibe como remuneración mensual S/.600,00 y trabaja de lunes a sá
bado. ¿A cuánto ascenderá su remuneración b r u ta mensual si falta injustificadamente un
día laborable de la semana?
Se divide la remuneración mensual (600) entre 30 días, pues solo ha faltado un día.
9. Ju an Cabrera trabajador de la empresa SORO SAC demanda su reposición, éste fue des
pedido sin causa justa debido a que se ausento de sus funciones desde el día cinco al once
de febrero de 2010 ; sin embargo, tuvo como justificación de dichas ausencias la incapaci
dad en la que se encontraba debido a que sufrió de una lumbalgia ciática, lo cual es corro
borado con el certificado de incapacidad presentado a través de la carta de descargos. Ud.
cómo juez qué resuelve?
Declaró FUNDADA la demanda de Juan, concluyendo que el demandante no incurrió en la
falta grave señalada en la ley, abandono de trabajo, debido a que presentó sus documentos
justifícatenos al momento de realizar sus descargos ante la imputación formulada.
10. Si Ju an inicia sus labores al servicio del Estado mediante un Contrato Administrativo de
Servicios, y luego de su vencimiento continúa laborando ¿Se produce una prórroga auto
mática del contrato de servicios en sus mismos términos?
Según el IV PLENO JURISDICCIONAL SUPREMO EN MATERIAS LABORAL Y PREVISIONAL
(Tema 2) Pub. 13.05.2016 La respuesta sería afirmativa. Si Juan ha iniciado sus labores al servi
cio del Estado mediante un Contrato Administrativo de Servicios, y luego de su vencimiento
continúa laborando, se produce una prórroga automática de dicho contrato en sus mismos
térm inosy porel mismo plazo.
11. La señorita Patricia Suyón es contratada bajo la modalidad CAS durante la emergen
cia sanitaria por el Covid-19, para apoyo en las tareas de prevención, control, diagnóstico
y tratamiento de los pacientes contagiados, habiéndose renovado su contrato de modo
sucesivo.
