S/. 72,000.00 soles.
En este caso, el trabajador tiene 10 años y medio, lo que se traduce en 10 años y medio de re
muneración y media mensual. El monto total se calcula como sigue:
10 años x 6,000.00 soles (remuneración mensual) = 60,000.00 soles.
0.5 años x 6,000.00 soles (remuneración media mensual) = 3,000.00 soles.
Total: 60,000.00 soles + 3,000.00 soles = 63,000.00 soles.
Además, se debe agregar el 25% de la remuneración mensual por cada año completo de ser
vidos, que es:
10 años x 6,000.00 soles x 0.25 = 15,000.00 soles.
Total: 63,000.00 soles + 15,000.00 soles = 78,000.00 soles.
Sin embargo, como el monto no puede exceder 12 remuneraciones, se ajusta a 12 remunera
ciones mensuales, que es:
12 x 6,000.00 soles = 72,000.00 soles.
