13. S o fía t r a b a ja en la e m p r e s a B a te ría s El R ayo S A A y d e a c u e rd o a su c ó m p u to cree que
c u m p lió con d e l ré c o rd vacacional c o rre s p o n d ie n te . S e ñ a le u s te d sí los s ig u ie n te s c o n c e p
to s se c o n s id e ra n c o m o d ía s e fe c tiv o s p a ra el c ó m p u to d e l ré c o rd vacacional:
Establecida la oportunidad del descanso vacacional de Sofía, sus vacaciones se inician aun
cuando coincida con el día de descanso semanal, feriado o día no laborable en el centro de
trabajo, toda vez, que la norma señala días calendarios.
Para efectos del récord vacacional, se considera como días efectivos de trabajo los siguientes:
a. La jornada ordinaria mínima de cuatro horas.
b. La jornada cumplida en día de descanso cualquiera que sea el número de horas laborado.
c. Las horas de sobretiempo en número de cuatro o más en un día.
d. Las inasistencias por enfermedad común, por accidente de trabajo o enfermedad profe
sional, en todos los casos solamente los primeros sesenta (60) días dentro de cada año de
servicios.
e. El descanso previo y posterior al parto.
f. El permiso sindical.
g. Las faltas o inasistencias autorizadas por ley, convenio Individual o colectivo o decisión
del empleador.
h. El período vacacional correspondiente al año anterior.
I. Los días de huelga, salvo que haya sido declarada improcedente o ilegal.
