El s e ñ o r P o sto carrero fo rm u ló su re c la m o administrativo,y al ser desestimado, interpone d e
m a n d a laboral d e sep o síción , alegando haber sido o b je to de despido fr a u d u le n to al u tiliz a r
se c o n tra to s m o d a le s y c o n tra to s CAS d e s n a tu ra liz a d o s p a ra e n c u b rir lab o res p e rm a n e n te s .
R esp ecto d e es ta p re te n s ió n , d e a c u e rd o a los h ech o s s e ñ a la d o s :
La demanda es amparable por cuanto la entidad habría infringido la prohibición de contratar
antes de un año a trabajadores estables mediante contratos modales. En este caso, el señor
Portocarrero prestó servidos de manera continua bajo distintas modalidades contractuales,
lo que podría configurar una desnaturalización de los contratos modales y un despido frau
dulento.
R esp ecto d e l m is m o caso, s o b re la a p lic a c ió n d e l p rin c ip io d e m é rito :
La reposición en el cargo no puede implicar el reconocimiento de un cargo, categoría o nivel
remunerativo en el CAP o PAP, o cualquier documento de gestión, ni su inclusión en planillas
del personal permanente de la entidad. Esto se debe a que la reposición es una medida de
protección contra el despido arbitrario, pero no implica necesariamente el reconocimiento de
un cargo o nivel remunerativo específico. La entidad mantiene su potestad de organización y
gestión de personal, siempre que respete los derechos laborales del trabajador.
16. La señora Violeta Quispe interpone demanda por hostilidad, en razón a que viene siendo
desplazada continuamente entre las clínicas del Grupo Sanitas, localizadas en puntos extre
mos de la dudad de Lima. Asimismo, las funciones a su cargo son variadas sin justificación
alguna, afectándole su categoría laboral y su dignidad como trabajadora, motivo por el que
cursó comunicación de emplazamiento a su empleador, y al no recibir respuesta, optó por la
terminación de su vínculo laboral, demandando indemnización por despido arbitrario.
A manera de alegación, señala que la clínica le asignaba funciones no establecidas en el
perfil del puesto, como contabilizar pacientes en emergencia, tomar control de tiempos de
admisión, reemplazo de personal por vacaciones, que no corresponden a una coordinadora.
La Sala Suprema anuló la sentencia emitida por la Sala Superior, indicando que se pronun
ciara sobre la afectación a la categoría y a l a dignidad de la trabajadora.
Respecto del primer extremo, la sentencia de vista deberá pronunciarse en sentido que:
La demanda debe ampararse dado que, entre las nuevas funciones asignadas, están conside
radas tareas de menor jerarquía que configura rebaja de categoría. La asignación de funciones
no establecidas en el perfil del puestoy de menor jerarquía puede ser considerada una rebaja
de categoría, lo que configura un despido arbitrario.
Respecto del mismo caso, con relación a la afectación a su dignidad como trabajadora, ex
tremo por el que redama una indemnización por daño moral:
Debe acreditarse que los actos de hostilidad denunciados tienen entidad distinta a la repara
ción por despido arbitrario para que proceda su reconocimiento. La indemnización por daño
