24041, los contratos han pasado a ser duración indeterminada, por lo que le corresponde su
derecho a la estabilidad.
En relación al mismo caso y al argumento del principio de mérito, cabe formular las a f ir
m a c io n e s siguientes:
El principio de mérito no aplica para el caso de los contratos temporales porque el personal
contratado no desarrolla carrera pública. El principio de mérito se refiere a que el ingreso,
permanencia, progresión y ascenso en el servicio civil se realiza mediante criterios de mérito
basados en la capacidad y desempeño. Sin embargo, en el caso de la señora Padilla, al haber
sido contratada temporalmente, no desarrollaba una carrera pública, por lo que el principio
de mérito no sería aplicable a su situación.
18. Un particular presentó una demanda de amparo con la f in a lid a d que se declare inapli
cable la Resolución Ministerial mediante la cual se dispuso a pasarlo de la situación militar
de actividad a la de retiro, por razones de renovación. El Tribunal Constitucional declaró
improcedente la demanda pues el demandante cobró su compensación por tiempo de ser
