Cuando la contratación implica una simple provisión de personal.
22. Está permitido que un extrabajador que laboró bajo contrato a tiempo indeterminado
suscriba contratos modales. ¿De ser cierto, en qué casos?
Los trabajadores permanentes que cesen no podrán ser recontratados bajo ningún tipo de contrato
sujeto a modalidad, salvo que haya transcurrido un año del cese. (Art. 78 del TUOde la LPCL).
