oportunidad de un mejor empleo en el extranjero, sin embargo, de eso ya ha pasado más
de tres años y hoy nuevamente ha regresado al país al estar gozando de periodo vacacio-
nal. El plazo para el cobro de sus b e n e fic io s sociales es de:
Cuatro años desde el cese del trabajador.
2 4 . En un Informe de Auditoría del OCI de un hospital del Sector Salud, se identificó irre
gularidades en la c o n tra ta c ió n de un servicio para una actividad por el Día de la Madre,
imputándose cargos de negligencia a diez funcionarios de la Dirección de Administración
y de la J e fa tu ra de Recursos Humanos, por incumplimiento de las normas de tesorería.
La directora de Administración habría dispuesto se utilíce recursos ordinarios del hospital
para los gastos de la referida actividad, materializado a través de requerimientos internos
y de documentos para la autorización del gasto, sin el sustento legal necesario.
Finalmente, el Informe del OCI recomienda a la entidad demandar a los funcionarios respon
sables a fin de reintegrar el monto utilizado indebidamente de S/i 0,000.00 en forma solidaria.
Respecto a la pretensión de pago de daños y perjuicios por responsabilidad patrimonial:
La demanda debe ser fundada porque está acreditado el daño, el elemento de antijuricidady
el nexo causal que exige el sistema de responsabilidad civil peruano.
En relación al mismo caso, los juzgados laborales que les correspondería conocer de la pre
tensión, conforme a lo establecido en la Nueva Ley Procesal de Trabajo, corresponde a los juz
gados especializados de trabajo conocer los procesos que versen sobre daño patrimonial o
extrapatrimonial.
25. El señor Enrique Baldovino celebró un contrato de trabajo con el Grupo Inmobiliario
Kroll, para ocupar el cargo de Gerente General Corporativo con una cláusula de salvaguarda
en caso de desvinculación de 12.5 remuneraciones mensuales, estimada en S/750,000.00.
Su designación se formalizó mediante acuerdo de Directorio del Grupo.
Al año siguiente, Kroll decide vender su participación accionaria a un grupo local, el mismo
que requiere reducir costos, y para ello opta por retirarle la confianza al señor Baldovino,
siendo el gerente general de una de las inmobiliarias del Grupo el encargado de transmi
tirle dicha decisión en forma verbal, sin pago de indemnización, teniendo como sustento
el V il Pleno Jurisdiccional Supremo Laboral de 2017.
Al no estar conforme con su desvinculación, el señor Baldovino interpone demanda laboral por
pago de indemnización convencional, invocando la cláusula pactada en su contrato de trabajo.
Respecto de la pretensión de pago de indemnización del señor Baldovino:
Debe prevalecer el criterio del TC, en el sentido que a los trabajadores de dirección y de con
fianza les alcanza la tutela resarcitoria, mas no la restitutoria.
