m e z c la s se usaba» a p a r t e d e ios p ro d u c to s e la b o ra d o s y se rv id o s p o r los proveedores» pe
tróleo y metildoroformo. Tanto los dueños como los encargados carecían de elementales
conocimientos químicos en relación con los productos que manejaban. En ese ambiente se
produjeron combinaciones que afectaban seriamente a los pulmones de los trabajadores,
causando molestias en las vías respiratorias, bronquitis con neumoníayfibrosis pulmonar,
lo que en varios casos provocó la muerte por insuficiencia respiratoria progresiva.
Respecto de una imputación administrativa a las empresas “A”y “B”, puede decirse que:
No atenían contra el principio de proscripción de la responsabilidad objetiva (art. Vil Título
preliminar CP) al im putara la persona jurídica. La responsabilidad objetiva se refiere a la res-
ponsabilidad de una persona jurídica por los daños causados por sus acciones u omisiones,
sin necesidad de demostrar la culpa o dolo de los responsables individuales. En este caso, las
empresas "A” y “B” carecían de medidas de seguridad y los dueños y encargados no tenían co
nocimientos químicos básicos, lo que llevó a la producción de combinaciones que afectaban
seriamente la salud de los trabajadores. La imputación administrativa a las empresas puede
ser justificada por la responsabilidad objetiva, ya que las empresas eran las que tenían el de
ber de garantizar las condiciones de salud de los trabajadores y no cumplieron con ese deber.
1. Antonio Ramírez interpone una demanda de amparo contra la O fic in a de Normaliza
ción Previsional solicitando, como petitorio, que se declare la nulidad de la resolución que
le deniega la pensión de jubilación. Admitida a trámite la demanda, el Juez Especializado
Constitucional competente de la Corte Superior de Lima f i ja fecha para la realización de la
Audiencia Única y notifica la demanda a la ONP. Luego de que la ONP contestó la deman
da, y después de que se realizó la Audiencia Única, el Juez expide sentencia declarando
infundada la demanda. Antonio Ramírez interpone recurso de apelación contra esta sen
tencia. Antes de que se realice la Vista de la Causa en la Sala Constitucional competente de
la Corte Superior de Lima, Antonio Ramírez ofrece un medio probatorio que no requiere
actuación.
Si Usted es un Juez Superior integrante de la Sala a cargo del trámite del recurso de apela
ción, propondría a la Sala:
Que admita el medio probatorio únicamente si tiene como finalidad acreditar hechos tras
cendentes para el proceso. En este caso, el medio probatorio ofrecido por Antonio Ramírez
después de que se realizó la Audiencia Única y antes de que se realice la Vista de la Causa
en la Sala Constitucional competente de la Corte Superior de Lima no tiene como finalidad
acreditar hechos trascendentes para el proceso, ya que lasentenciaya ha sido em itiday no hay
oportunidad para su valoración.
