la Ley de Reforma Constitucional “Ley 28389”- que modifica la Primera Disposición Final y
Transitoria de la Constitución sobre el régimen pensionario del Decreto Ley 20530 son:
Cierre definitivo del régimen pensionario del Decreto Ley 20530.
