o b s ta n te haber p re s e n ta d o el d o c u m e n to a la aseguradora co m o a la e m p r e s a minera, sin
o b te n e r respuesta.
Frente a filo, el señor Villaverde inicia proceso ju d ic ia l para que se le otorgue pensión de
in v a lid e z , in v o c a n d o el silencio a d m in is tr a tiv o n e g a tiv o recogido en la Ley N ° 27444.
R esp ecto de la p re te n s ió n incoada, el c r ite rio Segal que corresponde aplicarse es:
La demanda debe declararse infundada, por cuanto conforme al procedimiento establecido
por la compañía de seguros, el actor debió someterse a exámenes a cargo de los peritos de la
aseguradora.
R esp ec to d e l m is m o caso, m a r q u e la a f ir m a c ió n co rrec ta:
No cabe excepción de falta de agotamiento de la vía administrativa puesto que los trámites
inherentes a la pensión de invalidez, en este caso, corresponden a entidades privadas y no
públicas.
4. ¿Prescribe para el pensionista la facultad de reclamar los montos pensionarios devengados?
La facultad del pensionista de reclamar los montos pensionarios devengados es imprescripti
ble. Este beneficio de imprescriptibilidad no es extensible a sus herederos.
Solo hay prescripción si ya existe una suma líquida de las pensiones devengadas por entregar
y el pensionista no la reclama.
El plazo de prescripción predeterminado por Ley es de tres años en el caso del Régimen Previ-
sional regulado por el Decreto Ley 20530, según lo dispuesto en su artículo 56o. Para los demás
Regímenes Previsionales administrados por el Estado el plazo de prescripción es de diez años,
según lo dispuesto por el artículo 2001 inciso 1 del Código Civil.
5. Les corresponde a los pensionistas del Régimen 20530, de las entidades que se encuen
tran reguladas por el Fondo de Financiamíento de la Actividad Empresarial del Estado
(FONAFE), el pago de las bonificaciones reguladas en los Decretos de Urgencia N° 090-96,
¿N ° 073-97 y N° 011-99?
Conforme al IV PLENO JURISDICCIONAL SUPREMO EN MATERIAS LABORAL Y PREVISIO-
NAL(Tema4). En aquellos casos que se trate de empresas con participación estatal, bajo la ad
ministración de FONAFE, no les corresponde a sus pensionistas el pago de los beneficios otorga
dos por los Decretos de Urgencia N° 090-96, N °073-9 7 y N° 011-99, por cuando dichas empresas
se encuentran expresamente excluidas por estas normas. En aquellos casos que se trate de enti
dades que no son empresas con participación estatal,y están bajo la administración de FONAFE,
solo les corresponde a sus pensionistas el pago de los beneficios otorgados por los Decretos de
Urgencia N° 090-96, N° 073-9 7 y N° 011-99, si no existe una negociación colectiva que les haya
otorgado incrementos remunerativos, en los años 1996,1997y 1999, respectivamente.
6 . El Señor Baltazar Munive laboró para la “Empresa A” por un lapso de 25 años 10 meses, y
cuenta con todas sus boletas de pago donde se advierte el descuento por Seguridad Social.
