7. El s e ñ o r R a fa e l Falcón p o s tu ló d e m a n d a c o n te n c io s o a d m in is tr a tiv a en la v ía la b o r a l a
fin d e q u e se r e a ju s ta r a su p e n s ió n d e c e s a n tía e n eS e x tr e m o r e fe r id o a Sa b o n ific a c ió n es
p e c ia l p o r p re p a ra c ió n de clases y evaluación, p o r haber sido p ro fe s o r de educación inicial
en laUGELPiura.
En la parte final de la sentencia, se aprecia que la base de cálculo sería la últim a remuneración
anterior a su cese y “desde el día siguiente de la expedición de la sentencia hasta el cum pli
miento del pago de la continuay permanente”, extremo que quedó firme.
8. Al emitirse en ejecución de sentencia un informe pericial, toma en cuenta para efectos
del reajuste peticionado, la última remuneración anterior al cese del actor, resultando un
monto inferior al haber quedado congelado el monto de la citada b o n ific a c ió n .
Al no estar conforme con el extremo referido, el actor interpone apelación contra el conte
nido del informe, alegando que estaría incurso en causal de nulidad.
Tratándose el derecho a la pensión de un derecho fundamental, conforme a la jurispru
dencia del TC y normatividad vigente, podría postularse acción de amparo en alguno de
estos supuestos:
El derecho a la nivelación pensionarla no forma parte del contenido esencial del derecho a la
pensión, por lo que no es procedente el amparo.
Según la jurisprudencia del Tribunal Constitucional, el contenido esencial del derecho funda
mental a la pensión se refiere a la garantía de acceso a una pensión, no ser privado arbitraria
mente de ella,y percibir una pensión mínima vital. La nivelación pensionarla, en este caso, no
se encuentra dentro de estos elementos esenciales, por lo que no es susceptible de protección
a través del proceso de amparo.
